&lt;li&gt;&lt;a href=&quot;#_ข้อควรระวังและมาตรการบรรเทา&quot;&gt;ข้อควรระวังและมาตรการบรรเทา&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_บทเรียนที่ได้รับ&quot;&gt;บทเรียนที่ได้รับ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การตรวจสอบขั้นสุดท้าย&quot;&gt;การตรวจสอบขั้นสุดท้าย&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ลิงก์&quot;&gt;ลิงก์&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_เอกสารทางการ&quot;&gt;เอกสารทางการ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_เครื่องมือที่กล่าวถึง&quot;&gt;เครื่องมือที่กล่าวถึง&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_เพื่อศึกษาเพิ่มเติม&quot;&gt;เพื่อศึกษาเพิ่มเติม&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
