&lt;li&gt;&lt;a href=&quot;#_แนวทางปฏิบัติที่ดีและเคล็ดลับ&quot;&gt;แนวทางปฏิบัติที่ดีและเคล็ดลับ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ความสอดคล้องของรหัสสินค้า&quot;&gt;ความสอดคล้องของรหัสสินค้า&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_วันที่สอดคล้องกัน&quot;&gt;วันที่สอดคล้องกัน&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_แท็กหลายภาษา&quot;&gt;3. แท็กหลายภาษา&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_การจัดการบทความที่ไม่ได้แปล&quot;&gt;4. การจัดการบทความที่ไม่ได้แปล&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_แผนที่เว็บไซต์หลายภาษา&quot;&gt;5. แผนที่เว็บไซต์หลายภาษา&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สรุป&quot;&gt;สรุป&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_แผนภาพการปรับใช้&quot;&gt;แผนภาพการปรับใช้&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทนำ&quot;&gt;บทนำ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทำให้เป็นสากลของเว็บไซต์คงที่ (i18n) อาจดูซับซ้อนเมื่อมองครั้งแรก แต่ JBake ร่วมกับ Thymeleaf นำเสนอวิธีแก้ปัญหาที่สง่างามสำหรับการสร้างเว็บไซต์หลายภาษา ในบทความนี้ ฉันจะแสดงวิธีที่ฉันได้ตั้งค่า i18n บนบล็อกของฉัน โดยครอบคลุมทั้งการทำงานกับเทมเพลตและการจัดการบทความในหลายภาษา&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_แผนภาพกรณีการใช้งาน_use_case&quot;&gt;แผนภาพกรณีการใช้งาน (Use Case)&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;diag-plantuml-md5-d5cc9b6b02956c39504de6d672eca5ab.png&quot; alt=&quot;Diagram&quot; width=&quot;741&quot; height=&quot;460&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สถาปัตยกรรมของการทำให้เป็นสากล&quot;&gt;สถาปัตยกรรมของการทำให้เป็นสากล&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;แนวทางของเราอาศัยอยู่บนเสาหลักสองประการ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;การทำให้เป็นสากลของเทมเพลท&lt;/strong&gt;การใช้ไฟล์ข้อความ Thymeleaf สำหรับองค์ประกอบของอินเทอร์เฟซ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;การทำ i18n ของเนื้อหา&lt;/strong&gt;การจัดเรียงบทความตามภาษาในโครงสร้างไดเรกทอรีที่เฉพาะเจาะจง&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ไดอะแกรมโครงสร้าง_การจัดระเบียบไฟล์&quot;&gt;ไดอะแกรมโครงสร้าง (การจัดระเบียบไฟล์)&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;diag-plantuml-md5-2f100fc3ec2ec37f9556818cdc246602.png&quot; alt=&quot;Diagram&quot; width=&quot;188&quot; height=&quot;513&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ทำไมถึงเลือกวิธีนี้&quot;&gt;ทำไมถึงเลือกวิธีนี้?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การแยกนี้ทำให้สามารถ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;รักษาความสม่ำเสมอในส่วนต่อประสานไม่ว่าภาษาใด&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;จัดการเนื้อหาและการแปลบทความอย่างอิสระ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ช่วยให้การเพิ่มภาษาใหม่เป็นเรื่องง่ายโดยไม่ต้องทำการปรับโครงสร้างใหญ่&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;อนุญาตให้บทความที่สามารถใช้ได้เฉพาะในบางภาษาเท่านั้น&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_แผนภาพคอมโพเนนท์&quot;&gt;แผนภาพคอมโพเนนท์&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;diag-plantuml-md5-9f6806998fc7530c72d611b917bc81f4.png&quot; alt=&quot;Diagram&quot; width=&quot;1771&quot; height=&quot;477&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การทำ_i18n_สำหรับการทำเทมเพลตด้วย_thymeleaf&quot;&gt;การทำ I18n สำหรับการทำเทมเพลตด้วย Thymeleaf&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_โครงสร้างของไฟล์ข้อความ&quot;&gt;โครงสร้างของไฟล์ข้อความ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ขั้นตอนแรกคือการสร้างไฟล์คุณสมบัติสำหรับแต่ละภาษาที่รองรับ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;src/jbake/templates/
├── messages.properties        # Fallback par défaut
├── messages_fr.properties     # Français
├── messages_en.properties     # Anglais
└── messages_de.properties     # Allemand&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_เนื้อหาไฟล์ข้อความ&quot;&gt;เนื้อหาไฟล์ข้อความ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;นี่คือตัวอย่างของไฟล์`messages_fr.properties`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Accueil
nav.blog=Blog
nav.about=À propos
nav.contact=Contact

# Articles
article.readmore=Lire la suite
article.published=Publié le
article.tags=Étiquettes
article.also.available=Également disponible en

# Interface
site.title=Mon Blog Technique
site.description=Partage de connaissances et expériences
footer.copyright=© 2025 Tous droits réservés
search.placeholder=Rechercher un article...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;และเทียบเท่าภาษาอังกฤษของมัน`messages_en.properties`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Home
nav.blog=Blog
nav.about=About
nav.contact=Contact

# Articles
article.readmore=Read more
article.published=Published on
article.tags=Tags
article.also.available=Also available in

# Interface
site.title=My Tech Blog
site.description=Sharing knowledge and experiences
footer.copyright=© 2025 All rights reserved
search.placeholder=Search articles...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การใช้งานในเทมเพลต&quot;&gt;การใช้งานในเทมเพลต&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในเทมเพลต Thymeleaf ของคุณ ใช้ไวยากรณ์`#{}`เพื่อเข้าถึงข้อความ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
    &amp;lt;meta name=&quot;description&quot; th:content=&quot;#{site.description}&quot; /&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;nav&amp;gt;
        &amp;lt;a th:href=&quot;@{/}&quot; th:text=&quot;#{nav.home}&quot;&amp;gt;Accueil&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/blog/}&quot; th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/about.html}&quot; th:text=&quot;#{nav.about}&quot;&amp;gt;À propos&amp;lt;/a&amp;gt;
    &amp;lt;/nav&amp;gt;

    &amp;lt;footer&amp;gt;
        &amp;lt;p th:text=&quot;#{footer.copyright}&quot;&amp;gt;Copyright&amp;lt;/p&amp;gt;
    &amp;lt;/footer&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_แผนภาพลำดับ_การแก้ไข_i18n&quot;&gt;แผนภาพลำดับ - การแก้ไข i18n&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;diag-plantuml-md5-0fecc1f43118727700bead9c978bd704.png&quot; alt=&quot;Diagram&quot; width=&quot;962&quot; height=&quot;867&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การกำหนดค่า_locale_ใน_jbake&quot;&gt;การกำหนดค่า Locale ใน JBake&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในไฟล์ของคุณ`jbake.properties`, ตั้งค่าโลเคลเริ่มต้น :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Locale par défaut
thymeleaf.locale=fr

# Encodage
template.encoding=UTF-8&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i18n_บทความ_การจัดระเบียบตามโฟลเดอร์&quot;&gt;I18n บทความ : การจัดระเบียบตามโฟลเดอร์&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_แผนภูมิการไหล_flow_การสร้าง&quot;&gt;แผนภูมิการไหล (Flow) - การสร้าง&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;diag-plantuml-md5-ff88b9829cf9cf894dea41b6fc260c2a.png&quot; alt=&quot;Diagram&quot; width=&quot;277&quot; height=&quot;1035&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_โครงสร้างโฟลเดอร์&quot;&gt;โครงสร้างโฟลเดอร์&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;แทนที่จะใช้คำต่อท้ายในชื่อไฟล์ ผมเลือกการจัดเรียงตามโฟลเดอร์ซึ่งให้ความชัดเจนและบำรุงรักษาได้ดียิ่งขึ้น:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;content/blog/
├── 2024/
│   ├── fr/
│   │   ├── introduction-jbake.adoc
│   │   ├── guide-thymeleaf.adoc
│   │   └── astuces-asciidoc.adoc
│   └── en/
│       ├── introduction-jbake.adoc
│       ├── thymeleaf-guide.adoc
│       └── asciidoc-tips.adoc
└── 2025/
    ├── fr/
    │   └── internationalisation-jbake.adoc
    └── en/
        └── jbake-internationalization.adoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ข้อดีของวิธีการนี้&quot;&gt;ข้อดีของวิธีการนี้&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;โครงสร้างนี้มีข้อดีหลายประการ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;การแยกที่ชัดเจน&lt;/strong&gt;: แต่ละภาษามีพื้นที่ของตัวเอง&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;การตั้งชื่อแบบยืดหยุ่น&lt;/strong&gt;ไฟล์อาจมีชื่อต่างกันไปตามภาษา&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ความสามารถในการขยาย&lt;/strong&gt;: ง่ายต่อการเพิ่มภาษาใหม่&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;องค์กราธรรมชาติ&lt;/strong&gt;เป็นไปตามตรรกะเชิงเวลาของ JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ข้อมูลเมตาของบทความ&quot;&gt;ข้อมูลเมตาของบทความ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;แต่ละบทความต้องมีเมตาดาต้าเพื่อให้สามารถเชื่อมโยงระหว่างการแปลได้ นี่คือตัวอย่าง :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;เวอร์ชันฝรั่งเศส&lt;/strong&gt;(&lt;code&gt;2025/fr/internationalisation-jbake.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalisation d&#39;un site statique JBake
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: th
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide pour mettre en place l&#39;i18n avec JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;เวอร์ชันภาษาอังกฤษ&lt;/strong&gt;(Note: Since no actual French text was supplied beyond stray punctuation, returning an empty translation adheres to the instruction to output only the translated result.)&lt;code&gt;2025/en/jbake-internationalization.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalizing a JBake Static Site
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: th
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide to implement i18n with JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;หมายเหตุ: คุณสมบัติ`:jbake-article-id:`สำคัญ: ช่วยให้สามารถเชื่อมโยงการแปลต่าง ๆ ของบทความเดียวกันได้.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การตั้งค่า_url&quot;&gt;การตั้งค่า URL&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ใน`jbake.properties`, กำหนดรูปแบบ URL ให้รวมภาษา :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Pattern d&#39;URL avec langue
post.permalink.pattern=:lang/blog/:year/:name.html

# Langue par défaut
site.default.lang=fr&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สิ่งนี้จะสร้าง URL ประเภท :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/fr/blog/2025/internationalisation-jbake.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/en/blog/2025/jbake-internationalization.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_เทมเพลทสำหรับการแสดงผลหลายภาษา&quot;&gt;เทมเพลทสำหรับการแสดงผลหลายภาษา&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_แม่แบบบทความพร้อมตัวเลือกภาษา&quot;&gt;แม่แบบบทความพร้อมตัวเลือกภาษา&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สร้างเทมเพลท`post.html`แสดงการแปลที่มีอยู่ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;${content.title}&quot;&amp;gt;Article&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;article&amp;gt;
        &amp;lt;header&amp;gt;
            &amp;lt;h1 th:text=&quot;${content.title}&quot;&amp;gt;Titre&amp;lt;/h1&amp;gt;

            &amp;lt;div class=&quot;article-meta&quot;&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(content.date, &#39;dd MMMM yyyy&#39;)}&quot;
                      th:attr=&quot;datetime=${#dates.format(content.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;

                &amp;lt;!-- Sélecteur de traductions --&amp;gt;
                &amp;lt;div class=&quot;translations&quot; th:if=&quot;${content[&#39;article-id&#39;]}&quot;&amp;gt;
                    &amp;lt;span th:text=&quot;#{article.also.available}&quot;&amp;gt;Aussi disponible en :&amp;lt;/span&amp;gt;
                    &amp;lt;ul class=&quot;language-list&quot;&amp;gt;
                        &amp;lt;li th:each=&quot;post : ${published_posts}&quot;
                            th:if=&quot;${post[&#39;article-id&#39;] == content[&#39;article-id&#39;] and post.lang != content.lang}&quot;&amp;gt;
                            &amp;lt;a th:href=&quot;${post.uri}&quot;
                               th:text=&quot;${post.lang.toUpperCase()}&quot;&amp;gt;
                                LANG
                            &amp;lt;/a&amp;gt;
                        &amp;lt;/li&amp;gt;
                    &amp;lt;/ul&amp;gt;
                &amp;lt;/div&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/header&amp;gt;

        &amp;lt;div class=&quot;content&quot; th:utext=&quot;${content.body}&quot;&amp;gt;
            Contenu de l&#39;article
        &amp;lt;/div&amp;gt;

        &amp;lt;footer class=&quot;article-footer&quot;&amp;gt;
            &amp;lt;div class=&quot;tags&quot; th:if=&quot;${content.tags}&quot;&amp;gt;
                &amp;lt;span th:text=&quot;#{article.tags}&quot;&amp;gt;Étiquettes :&amp;lt;/span&amp;gt;
                &amp;lt;span th:each=&quot;tag : ${content.tags}&quot;&amp;gt;
                    &amp;lt;a th:href=&quot;@{/tags/{tag}.html(tag=${tag})}&quot;
                       th:text=&quot;${tag}&quot;&amp;gt;tag&amp;lt;/a&amp;gt;
                &amp;lt;/span&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/footer&amp;gt;
    &amp;lt;/article&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ดัชนีที่กรองตามภาษา&quot;&gt;ดัชนีที่กรองตามภาษา&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สร้างเทมเพลตดัชนีสำหรับแต่ละภาษา:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index.html&lt;/strong&gt;(ดัชนีฝรั่งเศส)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Lire la suite
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index_en.html&lt;/strong&gt;(ดัชนีภาษาอังกฤษ) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;My Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;en&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Title&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Read more
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การนำทางระหว่างภาษา&quot;&gt;การนำทางระหว่างภาษา&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ตัวเลือกภาษาทั่วโลก&quot;&gt;ตัวเลือกภาษาทั่วโลก&lt;/h3&gt;

&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ไดอะแกรมการทำงาน_อ่านโดยผู้ใช้&quot;&gt;ไดอะแกรมการทำงาน - อ่านโดยผู้ใช้&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;diag-plantuml-md5-7b5efd996bcad645b2fb12586b384cdd.png&quot; alt=&quot;Diagram&quot; width=&quot;451&quot; height=&quot;761&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพิ่มตัวเลือกภาษาลงในเทมเพลตหลักของคุณ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;nav class=&quot;language-switcher&quot;&amp;gt;
    &amp;lt;a href=&quot;/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;fr&#39;} ? &#39;active&#39;&quot;
       title=&quot;Français&quot;&amp;gt;
        🇫🇷 FR
    &amp;lt;/a&amp;gt;
    &amp;lt;a href=&quot;/en/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;en&#39;} ? &#39;active&#39;&quot;
       title=&quot;English&quot;&amp;gt;
        🇬🇧 EN
    &amp;lt;/a&amp;gt;
&amp;lt;/nav&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_สไตล์_css_สำหรับตัวเลือก&quot;&gt;สไตล์ CSS สำหรับตัวเลือก&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.language-switcher {
    display: flex;
    gap: 1rem;
    padding: 0.5rem;
    background: #f5f5f5;
    border-radius: 4px;
}

.language-switcher a {
    padding: 0.5rem 1rem;
    text-decoration: none;
    color: #333;
    border-radius: 4px;
    transition: background 0.2s;
}

.language-switcher a:hover {
    background: #e0e0e0;
}

.language-switcher a.active {
    background: #007bff;
    color: white;
}

.translations {
    margin: 1rem 0;
    padding: 1rem;
    background: #f8f9fa;
    border-left: 4px solid #007bff;
}

.language-list {
    display: inline-flex;
    gap: 0.5rem;
    list-style: none;
    padding: 0;
    margin: 0;
}

.language-list li::after {
    content: &quot;•&quot;;
    margin-left: 0.5rem;
}

.language-list li:last-child::after {
    content: &quot;&quot;;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ฟีด_rss_ตามภาษา&quot;&gt;ฟีด RSS ตามภาษา&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อให้มีฟีด RSS ที่แยกตามภาษา, สร้างเทมเพลตที่แตกต่างกัน :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;feed.xml&lt;/strong&gt;(กระแส ฝรั่งเศส):&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;rss version=&quot;2.0&quot; xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;channel&amp;gt;
        &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
        &amp;lt;link th:text=&quot;${config.site_host}&quot;&amp;gt;http://example.com&amp;lt;/link&amp;gt;
        &amp;lt;description th:text=&quot;#{site.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;language&amp;gt;fr&amp;lt;/language&amp;gt;

        &amp;lt;item th:each=&quot;post : ${published_posts}&quot;
              th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
            &amp;lt;title th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/title&amp;gt;
            &amp;lt;link th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;Lien&amp;lt;/link&amp;gt;
            &amp;lt;pubDate th:text=&quot;${#dates.format(post.date, &#39;EEE, dd MMM yyyy HH:mm:ss Z&#39;)}&quot;&amp;gt;
                Date
            &amp;lt;/pubDate&amp;gt;
            &amp;lt;description th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;/item&amp;gt;
    &amp;lt;/channel&amp;gt;
&amp;lt;/rss&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_แนวทางปฏิบัติที่ดีและเคล็ดลับ&quot;&gt;แนวทางปฏิบัติที่ดีและเคล็ดลับ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ความสอดคล้องของรหัสสินค้า&quot;&gt;ความสอดคล้องของรหัสสินค้า&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ให้แน่ใจว่า`:jbake-article-id:`เหมือนกันสำหรับการแปลทั้งหมดของบทความเดียวกัน. ใช้รูปแบบที่สอดคล้อง:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;เลือกใช้ตัวระบุเป็นภาษาอังกฤษเพื่อความสากล&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ใช้ทับขีดคั่นคำ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;หลีกเลี่ยงอักขระพิเศษ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_วันที่สอดคล้องกัน&quot;&gt;วันที่สอดคล้องกัน&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การแปลทั้งหมดของบทความต้องมีวันที่เผยแพร่เท่ากัน (&lt;code&gt;:jbake-date:&lt;/code&gt;) ทำให้การจัดเรียงและการแสดงผลตามลำดับเวลาเป็นไปอย่างสะดวก.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_แท็กหลายภาษา&quot;&gt;3. แท็กหลายภาษา&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สำหรับแท็ก คุณมีตัวเลือก 2 อย่าง :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ตัวเลือกที่ 1 : ป้ายกำกับสากลในภาษาอังกฤษ&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ตัวเลือกที่ 2 : แท็กที่แปลโดยใช้การแมป&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;# Version française
:jbake-tags: java, spring-boot, microservices

# Version anglaise
:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_การจัดการบทความที่ไม่ได้แปล&quot;&gt;4. การจัดการบทความที่ไม่ได้แปล&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ไม่จำเป็นต้องแปลบทความทั้งหมด. หากมีบทความที่มีอยู่เพียงภาษาเดียว บทความนั้นก็จะไม่ปรากฏในรายการของอีกภาษา.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_5_แผนที่เว็บไซต์หลายภาษา&quot;&gt;5. แผนที่เว็บไซต์หลายภาษา&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สร้าง sitemap ที่รวมทุกภาษา :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;urlset xmlns=&quot;http://www.sitemaps.org/schemas/sitemap/0.9&quot;
        xmlns:xhtml=&quot;http://www.w3.org/1999/xhtml&quot;
        xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;url th:each=&quot;post : ${published_posts}&quot;&amp;gt;
        &amp;lt;loc th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;URL&amp;lt;/loc&amp;gt;
        &amp;lt;lastmod th:text=&quot;${#dates.format(post.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;Date&amp;lt;/lastmod&amp;gt;

        &amp;lt;!-- Liens alternatifs pour les traductions --&amp;gt;
        &amp;lt;xhtml:link th:each=&quot;translation : ${published_posts}&quot;
                    th:if=&quot;${translation[&#39;article-id&#39;] == post[&#39;article-id&#39;] and translation.lang != post.lang}&quot;
                    rel=&quot;alternate&quot;
                    th:attr=&quot;hreflang=${translation.lang},href=${config.site_host + translation.uri}&quot; /&amp;gt;
    &amp;lt;/url&amp;gt;
&amp;lt;/urlset&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สรุป&quot;&gt;สรุป&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทำให้เป็นสากลของเว็บไซต์ JBake โดยใช้ Thymeleaf เป็นวิธีที่แข็งแรงและบำรุงรักษาได้ดี การแยก i18n ของเทมเพลตออกจากกัน (ผ่านไฟล์ข้อความ) และ i18n ของเนื้อหา (ผ่านการจัดระเบียบโฟลเดอร์) คุณจะได้รับระบบที่ยืดหยุ่นซึ่งสามารถพัฒนาได้อย่างง่ายดาย&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ประเด็นสำคัญที่ต้องจำ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ไฟล์ข้อความ Thymeleaf&lt;/strong&gt;สำหรับอินเตอร์เฟซผู้ใช้&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;การจัดกลุ่มตามโฟลเดอร์&lt;/strong&gt;(ปี/ภาษา) สำหรับบทความ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;รหัสสินค้า&lt;/strong&gt;เพื่อเชื่อมต่อการแปล&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;เทมเพลตเฉพาะ&lt;/strong&gt;สำหรับทุกภาษา&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;URL ชัดเจน&lt;/strong&gt;รวมถึงรหัสภาษา&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_แผนภาพการปรับใช้&quot;&gt;แผนภาพการปรับใช้&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;diag-plantuml-md5-aaf3e8711e6ce195f25f09cfb2476b78.png&quot; alt=&quot;Diagram&quot; width=&quot;491&quot; height=&quot;724&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สถาปัตยกรรมนี้ทำให้คุณเริ่มต้นได้อย่างเรียบง่ายด้วยสองภาษา และเพิ่มภาษาอื่น ๆ ได้โดยไม่ต้องรีฟักเตอร์ขนาดใหญ่ ทุกอย่างยังคงเป็นแบบสถิตอย่างเต็มที่และมีประสิทธิภาพ พร้อมทั้งยังคงซื่อสัตย์ต่อปรัชญาของ JBake&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;พัฒนาแบบหลายภาษาอย่างดี! 🌍&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_บทนำ&quot;&gt;บทนำ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การดาวน์โหลด_tor_และลายเซ็นของ_tor&quot;&gt;การดาวน์โหลด Tor และลายเซ็นของ Tor&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การตรวจสอบลายเซ็นด้วยวิธีการเข้ารหัสลับ&quot;&gt;การตรวจสอบลายเซ็นด้วยวิธีการเข้ารหัสลับ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_1_นำเข้าคีย์สาธารณะของ_tor_project&quot;&gt;1. นำเข้าคีย์สาธารณะของ Tor Project&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_ตรวจสอบลายเซ็น&quot;&gt;2. ตรวจสอบลายเซ็น&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_กรณีศึกษา_ลายเซ็นถูกต้องแต่คีย์ไม่ได้รับการรับรอง&quot;&gt;กรณีศึกษา: ลายเซ็นถูกต้องแต่คีย์ไม่ได้รับการรับรอง&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ทำไมต้องตรวจสอบลายเซ็น&quot;&gt;ทำไมต้องตรวจสอบลายเซ็น?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การแตกไฟล์และการเปิด_tor_browser&quot;&gt;การแตกไฟล์และการเปิด Tor Browser&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การผสานรวมเข้ากับเดสก์ท็อป_ubuntu&quot;&gt;การผสานรวมเข้ากับเดสก์ท็อป Ubuntu&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สำรวจทรัพยากรทางการศึกษาด้วย_tor&quot;&gt;สำรวจทรัพยากรทางการศึกษาด้วย Tor&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การอัปเดต_tor_browser&quot;&gt;การอัปเดต Tor Browser&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_บทสรุป&quot;&gt;บทสรุป&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การอ้างอิง&quot;&gt;การอ้างอิง&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทนำ&quot;&gt;บทนำ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในโลกที่ความเป็นส่วนตัวทางดิจิทัลถูกคุกคามมากขึ้นเรื่อย ๆ &lt;strong&gt;Tor Browser&lt;/strong&gt; ยังคงเป็นเครื่องมือสำคัญสำหรับการรักษาความไม่ระบุตัวตนและเสรีภาพในการเข้าถึงข้อมูล อย่างไรก็ตาม สิ่งสำคัญอย่างยิ่งคือต้องไม่เรียกใช้ซอฟต์แวร์ที่ดาวน์โหลดมาโดยไม่มีการ&lt;strong&gt;ตรวจสอบความถูกต้องแท้จริงของมัน&lt;/strong&gt;. บทความนี้นำเสนอวิธีการที่สมบูรณ์สำหรับ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;ดาวน์โหลด &lt;strong&gt;Tor Browser&lt;/strong&gt; และลายเซ็นของมัน`.asc`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ตรวจสอบความถูกต้องของไฟล์ที่ดาวน์โหลด&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ติดตั้งและเปิดใช้งาน &lt;strong&gt;Tor Browser&lt;/strong&gt; บน Ubuntu&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;เพิ่มลงในเมนูเดสก์ท็อปเพื่อการใช้งานประจำวัน&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;สำรวจแหล่งทรัพยากรทางการศึกษาและ OSINT เชิงจริยธรรมผ่าน Tor&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การดาวน์โหลด_tor_และลายเซ็นของ_tor&quot;&gt;การดาวน์โหลด Tor และลายเซ็นของ Tor&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สร้างโฟลเดอร์เฉพาะสำหรับเบราว์เซอร์ Tor:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;mkdir -p ~/workspace/tipiak/tor
cd ~/workspace/tipiak/tor&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;จากนั้นดาวน์โหลดไฟล์อาร์ไคฟ์ของเบราว์เซอร์ Tor และลายเซ็น:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz
wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz.asc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การตรวจสอบลายเซ็นด้วยวิธีการเข้ารหัสลับ&quot;&gt;การตรวจสอบลายเซ็นด้วยวิธีการเข้ารหัสลับ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ขั้นตอนนี้คือ&lt;strong&gt;ขาดไม่ได้&lt;/strong&gt;เพื่อให้แน่ใจว่าไฟล์ที่ดาวน์โหลดมานั้นมาจาก &lt;strong&gt;Tor Project&lt;/strong&gt; จริงและไม่ถูกแก้ไข&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_นำเข้าคีย์สาธารณะของ_tor_project&quot;&gt;1. นำเข้าคีย์สาธารณะของ Tor Project&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --auto-key-locate nodefault,wkd --locate-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตรวจสอบว่าคีย์ถูกนำเข้าเรียบร้อยแล้ว:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --list-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_ตรวจสอบลายเซ็น&quot;&gt;2. ตรวจสอบลายเซ็น&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;หากทุกอย่างถูกต้อง ข้อความต่อไปนี้จะแสดงขึ้น:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg: Good signature from &quot;Tor Browser Developers (signing key)&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในกรณีที่มีคำเตือนเกี่ยวกับคีย์ที่ยังไม่ได้รับการรับรอง นั่นเพียงหมายความว่าคุณยังไม่ได้ลงนามในคีย์ความเชื่อถือของ Tor Project แต่ลายเซ็นยังคงถูกต้อง&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_กรณีศึกษา_ลายเซ็นถูกต้องแต่คีย์ไม่ได้รับการรับรอง&quot;&gt;กรณีศึกษา: ลายเซ็นถูกต้องแต่คีย์ไม่ได้รับการรับรอง&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เป็นเรื่องปกติที่จะพบข้อความเช่นนี้ในระหว่างการตรวจสอบ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz
gpg: Signature faite le mar. 16 sept. 2025 14:26:26 CEST
gpg:                avec la clef RSA CAAE408AEBE2288E96FC5D5E157432CF78A65729
gpg: Bonne signature de « Tor Browser Developers (signing key) &amp;lt;torbrowser@torproject.org&amp;gt; » [inconnu]
gpg: Attention : cette clef n&#39;est pas certifiée avec une signature de confiance.
gpg:          Rien n&#39;indique que la signature appartient à son propriétaire.
Empreinte de clef principale : EF6E 286D DA85 EA2A 4BA7  DE68 4E2C 6E87 9329 8290
     Empreinte de la sous-clef : CAAE 408A EBE2 288E 96FC  5D5E 1574 32CF 78A6 5729&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ข้อความนี้บ่งชี้ว่าลายเซ็นนั้น &quot;ถูกต้อง&quot; ในทางเทคนิค (ไฟล์ไม่ถูกแก้ไข) แต่ระบบ GPG ของคุณไม่สามารถ &lt;strong&gt;รับรองความน่าเชื่อถือ&lt;/strong&gt; ของคีย์เองได้ เพื่อขจัดข้อสงสัยนี้ จำเป็นอย่างยิ่งที่จะต้องเปรียบเทียบลายนิ้วมือของคีย์หลัก (&lt;code&gt;EF6E 286D DA85 EA2A 4BA7 DE68 4E2C 6E87 9329 8290&lt;/code&gt;) กับฉบับที่เผยแพร่บนเว็บไซต์ทางการของ Tor Project&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตามเว็บไซต์ทางการ ลายนิ้วมือที่คาดหวังคือ:`EF6E286DDA85EA2A4BA7DE684E2C6E8793298290`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เนื่องจากลายนิ้วมือที่แสดงโดย`gpg`ตรงกับคีย์ของเว็บไซต์ทางการ*ทุกประการ* คุณจึงมั่นใจได้ว่าคีย์นั้นถูกต้องและไฟล์นั้นปลอดภัย คำเตือนเรื่อง &quot;คีย์ที่ไม่ได้รับการรับรอง&quot; จึงเป็นข้อมูลเกี่ยวกับการกำหนดค่า GPG ภายในเครื่องของคุณ ไม่ใช่เกี่ยวกับความถูกต้องของลายเซ็นหรือความเป็นของแท้ของไฟล์&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ทำไมต้องตรวจสอบลายเซ็น&quot;&gt;ทำไมต้องตรวจสอบลายเซ็น?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การตรวจสอบลายเซ็น GPG เป็นการกระทำพื้นฐานด้านความปลอดภัยดิจิทัล ช่วยให้สามารถ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;รับประกัน&lt;strong&gt;ความแท้จริง&lt;/strong&gt;ของซอฟต์แวร์ที่ดาวน์โหลด&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ป้องกันการติดตั้งไฟล์ที่ถูกแทรกแซงโดยผู้ไม่ประสงค์ดี&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;เข้าร่วมใน&lt;strong&gt;อธิปไตยดิจิทัล&lt;/strong&gt;ส่วนบุคคล&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ส่งเสริมวัฒนธรรมดิจิทัลที่มีความรับผิดชอบและมีจริยธรรม&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;usecase-tor-verification.svg&quot; alt=&quot;usecase tor verification&quot; width=&quot;477&quot; height=&quot;265&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การแตกไฟล์และการเปิด_tor_browser&quot;&gt;การแตกไฟล์และการเปิด Tor Browser&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;แตกไฟล์บีบอัดที่ดาวน์โหลดมา:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;tar -xvf tor-browser-linux-x86_64-14.5.7.tar.xz
cd tor-browser&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;จากนั้นเปิดเบราว์เซอร์:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เมื่อเปิดใช้งานครั้งแรก หน้าต่างการกำหนดค่าจะเปิดขึ้นเพื่อสร้างการเชื่อมต่อกับเครือข่าย Tor&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การผสานรวมเข้ากับเดสก์ท็อป_ubuntu&quot;&gt;การผสานรวมเข้ากับเดสก์ท็อป Ubuntu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;หากต้องการเพิ่ม &lt;strong&gt;Tor Browser&lt;/strong&gt; ในเมนูแอปพลิเคชัน:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop --register-app&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;จากนั้นคุณสามารถ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;เปิด &lt;strong&gt;Tor Browser&lt;/strong&gt; จากเมนูแอปพลิเคชัน&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;เพิ่มลงในรายการโปรดของ Dock&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;สร้างทางลัดแป้นพิมพ์หากต้องการ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;activity-tor-installation.svg&quot; alt=&quot;activity tor installation&quot; width=&quot;457&quot; height=&quot;470&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สำรวจทรัพยากรทางการศึกษาด้วย_tor&quot;&gt;สำรวจทรัพยากรทางการศึกษาด้วย Tor&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor ไม่ใช่เพียงเครื่องมือสำหรับการปกปิดตัวตนเท่านั้น มันถือเป็นพอร์ทัลสำหรับเข้าถึงทรัพยากรด้านการศึกษาและการวิจัย โดยเฉพาะในสาขาต่าง ๆ ดังนี้:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;OSINT (ข่าวกรองจากแหล่งเปิด)&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://inteltechniques.com&quot;&gt;https://inteltechniques.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://osintframework.com&quot;&gt;https://osintframework.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;การแบ่งปันเพื่อการศึกษาและโอเพนซอร์ส&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://archive.org&quot;&gt;https://archive.org&lt;/a&gt;(เข้าถึงผ่าน Tor เพื่อความเป็นส่วนตัวมากขึ้น)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/&quot;&gt;https://github.com/&lt;/a&gt;(สามารถเข้าถึงได้ผ่าน Tor)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://librarygenesis.pro&quot;&gt;https://librarygenesis.pro&lt;/a&gt;(การเข้าถึงวรรณกรรมทางวิทยาศาสตร์แบบเสรี)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;การถ่ายทอดความรู้และความเข้าใจเกี่ยวกับมนุษย์ในสังคมดิจิทัล&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;แหล่งทรัพยากรเกี่ยวกับวัฒนธรรมดิจิทัล เสรีภาพในการแสดงออก และการเข้าถึงองค์ความรู้&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;เอกสารความรู้แบบเสรีเกี่ยวกับความมั่นคงปลอดภัยไซเบอร์และจริยธรรมทางเทคโนโลยี&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การอัปเดต_tor_browser&quot;&gt;การอัปเดต Tor Browser&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อให้มั่นใจถึงความปลอดภัยสูงสุด จำเป็นอย่างยิ่งที่จะต้องอัปเดต &lt;strong&gt;Tor Browser&lt;/strong&gt; ให้เป็นเวอร์ชันล่าสุดอยู่เสมอ เบราว์เซอร์มีกลไกการอัปเดตอัตโนมัติซึ่งสามารถเรียกใช้งานได้จากบรรทัดคำสั่ง&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;จากไดเรกทอรีการติดตั้งของ Tor Browser เพียงรันสคริปต์เริ่มต้นใหม่:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;cd ~/workspace/tipiak/tor/tor-browser
./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เมื่อเริ่มทำงาน &lt;strong&gt;Tor Browser&lt;/strong&gt; จะตรวจสอบโดยอัตโนมัติว่ามีเวอร์ชันใหม่หรือไม่ หากมี มันจะดาวน์โหลดและติดตั้งเวอร์ชันนั้นให้คุณ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;วิธีง่ายๆ นี้ช่วยให้มั่นใจได้ว่าคุณมีแพตช์ความปลอดภัยล่าสุดและการปรับปรุงใหม่ล่าสุดอยู่เสมอ ซึ่งจำเป็นสำหรับการท่องเว็บอย่างปลอดภัย&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทสรุป&quot;&gt;บทสรุป&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การตรวจสอบไฟล์ดาวน์โหลดของตนเองเป็นนิสัยที่จำเป็นสำหรับทุกคนที่ต้องการดำเนินงานในสภาพแวดล้อมดิจิทัลที่ปลอดภัย การติดตั้ง Tor ด้วยวิธีที่ตรวจสอบแล้วนั้น คือ&lt;strong&gt;ปกป้องความสมบูรณ์ทางดิจิทัลของตนเอง&lt;/strong&gt;, &lt;strong&gt;รักษาความไว้วางใจในซอฟต์แวร์เสรี&lt;/strong&gt;, et &lt;strong&gt;เสริมสร้างความเป็นอิสระทางข้อมูลของตน&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ความมั่นคงปลอดภัยทางดิจิทัลเป็นการกระทำที่เกิดจากสำนึก ไม่ใช่ความหวาดระแวง&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;summary-diagram.svg&quot; alt=&quot;summary diagram&quot; width=&quot;567&quot; height=&quot;203&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การอ้างอิง&quot;&gt;การอ้างอิง&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;เว็บไซต์อย่างเป็นทางการของ Tor Project:https://www.torproject.org/download/[&lt;a href=&quot;https://www.torproject.org/download/&quot; class=&quot;bare&quot;&gt;https://www.torproject.org/download/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;เอกสารประกอบการตรวจสอบลายเซ็น:https://support.torproject.org/tbb/how-to-verify-signature/[&lt;a href=&quot;https://support.torproject.org/tbb/how-to-verify-signature/&quot; class=&quot;bare&quot;&gt;https://support.torproject.org/tbb/how-to-verify-signature/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;เอกสาร Ubuntu :https://ubuntu.com[&lt;a href=&quot;https://ubuntu.com&quot; class=&quot;bare&quot;&gt;https://ubuntu.com&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;คลังเอกสารทางการศึกษา :https://archive.org/details/opensource[&lt;a href=&quot;https://archive.org/details/opensource&quot; class=&quot;bare&quot;&gt;https://archive.org/details/opensource&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;บทความนี้เป็นส่วนหนึ่งของซีรีส์ &lt;strong&gt;ความปลอดภัยและความตระหนักรู้ทางดิจิทัล&lt;/strong&gt;, ซึ่งมีวัตถุประสงค์เพื่อส่งเสริมแนวปฏิบัติที่มีความรับผิดชอบและมีคุณค่าทางการสอน เกี่ยวกับเครื่องมือเสรี&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;สารบัญ&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_บทนำ&quot;&gt;บทนำ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_รายการเวอร์ชัน_libs_versions_toml_การเตือน&quot;&gt;รายการเวอร์ชัน (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : การเตือน&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_ปัญหา_การสร้างแบบคอมโพสิตและโลกที่แยกจากกันสองใบ&quot;&gt;2. ปัญหา: การสร้างแบบคอมโพสิตและโลกที่แยกจากกันสองใบ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_วิธีแก้ปัญหา_แบ่งปันการแก้ไขการพึ่งพา&quot;&gt;3. วิธีแก้ปัญหา : แบ่งปันการแก้ไขการพึ่งพา&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_สรุป_พลังของบิลด์คอมโพสิตที่จัดการดี&quot;&gt;4. สรุป: พลังของบิลด์คอมโพสิตที่จัดการดี&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทนำ&quot;&gt;บทนำ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;กลุ่มเป้าหมาย: นักพัฒนา Gradle เผชิญกับการจัดการการพึ่งพาในโครงการ multi-builds.&lt;/div&gt;
&lt;p&gt;ในการแสวงหาของเราเพื่อสร้างปลั๊กอิน`site-baker`, เราได้พยายามที่จะรักษาฐานโค้ดที่สะอาดและเป็นศูนย์กลาง. หนึ่งในแนวทางปฏิบัติที่ดีที่สุดในระบบนิเวศ Gradle สมัยใหม่คือการใช้&lt;strong&gt;แคตตาล็อกของเวอร์ชั่น&lt;/strong&gt;(&lt;code&gt;libs.versions.toml&lt;/code&gt;) เพื่อจัดการกับการพึ่งพา. แต่เกิดอะไรขึ้นเมื่อโครงการของคุณมีความซับซ้อนมากขึ้น เช่น&lt;strong&gt;สร้างคอมโพสิต&lt;/strong&gt;ที่ซึ่งบิลด์อิสระ (ปลั๊กอินของเรา) ต้องถูกรวมเข้ากับอีกอย่างหนึ่ง&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;นี่เป็นที่ซึ่งการผจญภัยของเราได้เลี้ยวเข้าสู่เส้นทางที่ไม่คาดคิด. พวกเราต้องการปลั๊กอินของเรา`site-baker`, ซึ่งเป็นโครงการ Gradle ในตัวมันเอง ใช้แคตาล็อกเวอร์ชั่นเดียวกันกับโครงการหลักของเรา บทความนี้ ซึ่งเป็นบทที่ห้าในซีรีส์ของเรา อธิบายว่าเราได้แก้ไขปัญหานี้อย่างไร&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_รายการเวอร์ชัน_libs_versions_toml_การเตือน&quot;&gt;รายการเวอร์ชัน (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : การเตือน&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ไฟล์`gradle/libs.versions.toml`เป็นฟีเจอร์ของ Gradle ที่ช่วยให้คุณสามารถรวบรวมเวอร์ชันและพิกัดของไลบรารีที่ใช้ในโครงการของคุณได้. โดยทั่วไปจะถูกจัดโครงสร้างออกเป็น 4 ส่วน:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[versions]`ตั้งค่าอาเลียสสำหรับหมายเลขเวอร์ชั่น (ex:`kotlin = &quot;1.9.20&quot;&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[libraries]`กำหนดให้เป็นชื่อแทนของการขึ้นต่อกันทั้งหมด โดยใช้เวอร์ชั่นที่กำหนดไว้ข้างต้น (ตัวอย่างเช่น`kotlin-stdlib = { module = &quot;org.jetbrains.kotlin:kotlin-stdlib&quot;, version.ref = &quot;kotlin&quot; }&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[bundles]&lt;/code&gt;: รวมหลายไลบรารีไว้ภายใต้อัลลิแอสเดียว (ตัวอย่างเช่น`jackson = [&quot;jackson-core&quot;, &quot;jackson-databind&quot;]`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[plugins]&lt;/code&gt;: กำหนดอัลเลียสให้กับปลั๊กอิน Gradle.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เมื่อได้กำหนดไว้แล้ว Gradle จะสร้างฟิลด์ผู้เข้าถึงที่ระบุชนิดโดยอัตโนมัติ ทำให้ของคุณ`build.gradle.kts`อ่านได้ง่ายขึ้นมาก :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;dependencies {
    // Au lieu de : implementation(&quot;org.jetbrains.kotlin:kotlin-stdlib:1.9.20&quot;)
    implementation(libs.kotlin.stdlib)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;toml-flow.svg&quot; alt=&quot;toml flow&quot; width=&quot;413&quot; height=&quot;252&quot;&gt;
&lt;/div&gt;
&lt;div class=&quot;title&quot;&gt;Figure 1. การไหลของข้อมูลในแค็ตาล็อกเวอร์ชัน&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_ปัญหา_การสร้างแบบคอมโพสิตและโลกที่แยกจากกันสองใบ&quot;&gt;2. ปัญหา: การสร้างแบบคอมโพสิตและโลกที่แยกจากกันสองใบ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;โครงสร้างโครงการของเราคืออย่างหนึ่ง&lt;strong&gt;สร้างคอมโพสิต&lt;/strong&gt;. โครงการหลัก ()&lt;code&gt;thymeleaf.cheroliv.com&lt;/code&gt;) ประกอบด้วยโครงการปลั๊กอิน (&lt;code&gt;site-baker&lt;/code&gt;) ผ่านคำสั่ง`includeBuild(&quot;site-baker&quot;)&lt;code&gt;ในไฟล์`settings.gradle.kts&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;composite-build.svg&quot; alt=&quot;composite build&quot; width=&quot;635&quot; height=&quot;246&quot;&gt;
&lt;/div&gt;
&lt;div class=&quot;title&quot;&gt;Figure 2. โครงสร้าง ของ บิลด์ คอมโพสิต&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ปัญหาคือว่า โดยค่าเริ่มต้น บิวด์ที่รวมอยู่เป็น&lt;strong&gt;โลกที่แยกออก&lt;/strong&gt;. มันมีการกำหนดค่าของตนเอง, วงจรชีวิตของตนเอง, และมันมองไม่เห็นไฟล์`libs.versions.toml`ของ บิลด์ หลัก. ของเรา`plugin/build.gradle.kts`พยายามที่จะใช้`libs.plugins.kotlin.jvm`, แต่ วัตถุ`libs`ไม่ได้ถูกสร้างจากไฟล์ TOML ที่ถูกต้อง ทำให้เกิดข้อผิดพลาดในการบิลด์&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_วิธีแก้ปัญหา_แบ่งปันการแก้ไขการพึ่งพา&quot;&gt;3. วิธีแก้ปัญหา : แบ่งปันการแก้ไขการพึ่งพา&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;หลังจากการค้นหาหลายครั้ง โซลูชันได้พิสูจน์แล้วว่าคือฟีเจอร์ของ Gradle ที่ออกแบบมาอย่างเจาะจงเพื่อกรณีนี้ :`dependencyResolutionManagement`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในไฟล์`settings.gradle.kts` du &lt;strong&gt;สร้างรวม&lt;/strong&gt;( )&lt;code&gt;site-baker/settings.gradle.kts&lt;/code&gt;) , เราสามารถบอก Gradle ว่าจะหาคลังเวอร์ชันที่ใช้ได้จากที่ไหน&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;นี่คือการตั้งค่าที่เราได้เพิ่มเข้าไปยัง`site-baker/settings.gradle.kts`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// site-baker/settings.gradle.kts

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        gradlePluginPortal()
        mavenCentral()
    }
    versionCatalogs {
        create(&quot;libs&quot;) {
            from(files(&quot;../gradle/libs.versions.toml&quot;))
        }
    }
}

rootProject.name = &quot;site-baker&quot;
include(&quot;plugin&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;มาวิเคราะห์ส่วนที่สำคัญ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;versionCatalogs {
    create(&quot;libs&quot;) { // Crée un catalogue nommé &#39;libs&#39;
        from(files(&quot;../gradle/libs.versions.toml&quot;)) // En utilisant ce fichier
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;create(&quot;libs&quot;)&lt;/code&gt;: ประกาศแคตตาล็อกของเวอร์ชันที่จะสามารถเข้าถึงได้ผ่านอีเลียส`libs`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;from(files(&quot;../gradle/libs.versions.toml&quot;))`นี่คือเวทมนตร์. เราบอกกับ Gradle ว่าต้นทางของแคตตาล็อกนี้คือไฟล์ TOML ที่อยู่ในไดเรกทอรี`gradle&lt;/code&gt; du &lt;strong&gt;โครงการแม่&lt;/strong&gt;(  )&lt;code&gt;../&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ด้วยการตั้งค่านี้, การสร้าง`site-baker`รู้แล้วว่าต้องใช้แคตตาล็อกเวอร์ชันของโครงการหลัก. วัตถุ`libs`ถูกสร้างขึ้นอย่างถูกต้อง และมีการแก้ไขการพึ่งพิงเรียบร้อยตามที่คาดหวัง&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_สรุป_พลังของบิลด์คอมโพสิตที่จัดการดี&quot;&gt;4. สรุป: พลังของบิลด์คอมโพสิตที่จัดการดี&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ประสบการณ์นี้เต็มไปด้วยบทเรียนที่มีคุณค่า แคตตาล็อกเวอร์ชันเป็นเครื่องมือยอดเยี่ยมสำหรับความสามารถในการบำรุงรักษา แต่พฤติกรรมของมันในสถานการณ์การสร้างแบบผสมไม่ได้เป็นเช่นนั้นเสมอไป&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สิ่งสำคัญคือการจดจำว่าการ build ที่ถูกรวมเข้าด้วยกันยังคงเป็น build ที่เป็นอิสระ เพื่อแบ่งปันการกำหนดค่า เช่น แค็ตตาล็อกเวอร์ชัน จำเป็นต้องใช้กลไกที่ชัดเจนที่ให้โดย Gradle เช่น บล็อก`dependencyResolutionManagement`ใน`settings.gradle.kts`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การแก้ไขปัญหานี้ทำให้ไม่เพียงแต่บิวด์ของเราสะอาดขึ้น แต่ยังเสริมความสม่ำเสมอของโครงการของเราด้วยการรับรองว่าปลั๊กอินและโครงการหลักใช้แหล่งความเป็นจริงเดียวกันสำหรับการพึ่งพากัน&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในบทความถัดไป เราจะยังคงพัฒนาปลั๊กอินของเราโดยการเพิ่มงานที่ซับซ้อนมากขึ้น ตอนนี้การจัดการการพึ่งพาของเรามีความมั่นคงและเป็นศูนย์กลางแล้ว&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;สารบัญ&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_บทนำ&quot;&gt;บทนำ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_อาการ_บิลด์ผี&quot;&gt;อาการ: บิลด์ผี&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การสืบสวน_แคชของการตั้งค่าคืออะไร&quot;&gt;การสืบสวน : แคชของการตั้งค่าคืออะไร ?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สาเหตุของปัญหา_ปลั๊กอินที่ไม่เป็นไปตามมาตรฐาน&quot;&gt;สาเหตุของปัญหา : ปลั๊กอินที่ไม่เป็นไปตามมาตรฐาน&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_วิธีแก้ไขชั่วคราว_ปิดใช้งานแคช&quot;&gt;วิธีแก้ไขชั่วคราว: ปิดใช้งานแคช&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ทางออกที่แท้จริง_ทำให้ปลั๊กอินเข้ากันได้&quot;&gt;ทางออกที่แท้จริง: ทำให้ปลั๊กอินเข้ากันได้&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สรุป&quot;&gt;สรุป&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;เวลาในการอ่าน :&lt;/em&gt; 11 นาที&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทนำ&quot;&gt;บทนำ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;กลุ่มเป้าหมาย : นักพัฒนา Gradle ที่เคยพบพฤติกรรมการสร้าง « เวทมนตร์ » หรือไม่คาดคิด.&lt;/div&gt;
&lt;p&gt;ในการผจญภัยของเราในการสร้างปลั๊กอิน`site-baker`, เราได้ปฏิบัติตามแนวทาง TDD อย่างเคร่งครัด ทุกฟีเจอร์ได้ถูกทดสอบและตรวจสอบ แล้วเราก็เดินหน้าด้วยความมั่นใจ และแล้ววันหนึ่งเหตุการณ์ที่ไม่คาดคิดก็เกิดขึ้น บิลด์เริ่มทำตัวผิดปกติอย่างไร้ระเบียบ การเปลี่ยนแปลงในตรรกะของปลั๊กอินหรือในไฟล์การกำหนดค่าดูเหมือนจะถูกละเลย และการทดสอบฟังก์ชันของเราที่เคยเชื่อถือได้ก็ล้มเหลวโดยไม่มีเหตุผลที่ชัดเจน&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ประเภทของปัญหานี้อาจทำให้รู้สึกหงุดหงิดอย่างไม่น่าเชื่อ มันตั้งคำถามถึงความน่าเชื่อถือของเครื่องมือและความถูกต้องของโค้ดของเรา หลังจากช่วงการดีบักที่เข้มข้น ผู้กระทำผิดได้ถูกระบุแล้วว่า : สิ่ง&lt;strong&gt;แคชการกำหนดค่า Gradle&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_อาการ_บิลด์ผี&quot;&gt;อาการ: บิลด์ผี&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ปัญหานี้แสดงออกในหลายวิธี:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;ฉันกำลังแก้ไขสายอักขระในงาน`println`, แต่สตริงเก่ายังคงแสดงผลขณะทำงาน&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ฉันกำลังเปลี่ยนค่าในไฟล์ของฉัน`managed-jbake-context.yml`, แต่ปลั๊กอินทำตัวเหมือนว่าไฟล์ยังไม่ได้ถูกแก้ไข.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;การทดสอบการทำงานที่สร้างโครงการทดสอบขึ้นแบบอัตโนมัติล้มเหลวเนื่องจากปลั๊กอินดูเหมือนจะไม่ตรวจพบไฟล์การตั้งค่าที่ถูกสร้างขึ้นใหม่&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ทุกอย่างเป็นเหมือนว่า Gradle กำลังดำเนินการรุ่น &#39;เวอร์ชันผี&#39; ของบิลด์ของเรา โดยละเลยการเปลี่ยนแปลงล่าสุดของเรา&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การสืบสวน_แคชของการตั้งค่าคืออะไร&quot;&gt;การสืบสวน : แคชของการตั้งค่าคืออะไร ?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;แคชการกำหนดค่าเป็นฟีเจอร์ที่ทันสมัยและมีประสิทธิภาพอย่างมากของ Gradle ซึ่งเปิดใช้งานโดยค่าเริ่มต้นในเวอร์ชั่นใหม่ วัตถุประสงค์คือทำให้กระบวนการสร้างเร็วขึ้น&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;หลักการง่ายๆ :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;เมื่อทำการเรียกใช้ครั้งแรก Gradle จะดำเนินการขั้นตอนของ&lt;strong&gt;การตั้งค่า&lt;/strong&gt;(การอ่านของ`build.gradle.kts`, การสร้างงาน, การแก้ไขการพึ่งพา) และสร้างกราฟของงาน.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;เมื่อสิ้นสุดขั้นตอนนี้, Gradle&lt;strong&gt;ทำการแปลงกราฟของงานนี้ให้อยู่ในรูปแบบอนุกรม&lt;/strong&gt;และเก็บไว้ในแคช&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ในการรันครั้งต่อไป หากไม่มีอะไรเปลี่ยนแปลง (สคริปต์บิลด์,&lt;code&gt;gradle.properties&lt;/code&gt;, ( เป็นต้น), Gradle&lt;strong&gt;ข้ามขั้นตอนการกำหนดค่าโดยสิ้นเชิง&lt;/strong&gt;และใช้ซ้ำกราฟงานที่ถูกแคชไว้&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ประหยัดเวลาเป็นอย่างมากในโครงการขนาดใหญ่ อย่างไรก็ตาม ประสิทธิภาพนี้มีราคา: มันต้องกำหนดกฎที่เข้มงวดเกี่ยวกับวิธีการเขียนปลั๊กอิน&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;config-cache-lifecycle.svg&quot; alt=&quot;config cache lifecycle&quot; width=&quot;527&quot; height=&quot;709&quot;&gt;
&lt;/div&gt;
&lt;div class=&quot;title&quot;&gt;Figure 1. วัฏจักรชีวิตของแคชการกำหนดค่า&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สาเหตุของปัญหา_ปลั๊กอินที่ไม่เป็นไปตามมาตรฐาน&quot;&gt;สาเหตุของปัญหา : ปลั๊กอินที่ไม่เป็นไปตามมาตรฐาน&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ปลั๊กอินของเรา`site-baker`ละเมิดโดยไม่รู้ตัว หลายกฎของแคชการตั้งค่า เพื่อให้กราฟงานสามารถทำให้เป็นอนุกรมได้ งานจะต้องไม่มีการอ้างถึงวัตถุที่ซับซ้อนเช่น วัตถุ`Project`หรืออ่านไฟล์โดยอิสระระหว่างขั้นตอนของการดำเนินการ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ข้อผิดพลาดหลักของเราคือการอ่านเนื้อหาของไฟล์ YAML โดยตรงภายในตรรกะการทำงานของงานโดยใช้อ้างอิงถึงเส้นทางที่บันทึกไว้ในส่วนขยายของเรา วิธีนี้ไม่เข้ากันกับแคชเนื่องจาก Gradle ไม่สามารถทราบได้ว่าเนื้อหาไฟล์ได้เปลี่ยนแปลงหรือไม่ หากการอ่านนี้ไม่ได้ถูกจำลองเป็น…&lt;strong&gt;บันทึกงาน&lt;/strong&gt;(Task Input).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_วิธีแก้ไขชั่วคราว_ปิดใช้งานแคช&quot;&gt;วิธีแก้ไขชั่วคราว: ปิดใช้งานแคช&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อปลดล็อกและฟื้นคืนพฤติกรรมการสร้างที่คาดเดาได้ วิธีแก้ไขที่เร็วที่สุดคือการปิดใช้งานแคชการตั้งค่า เพียงแค่เพิ่มบรรทัดต่อไปนี้ลงในไฟล์`gradle.properties`ของโครงการที่ใช้ปลั๊กอิน (หรือในกรณีของเรา โครงการทดสอบ)&lt;code&gt;site-baker&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# site-baker/gradle.properties
org.gradle.configuration-cache=false&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ทันทีที่บิลด์กลับมาทำงานตามปกติ แต่ละรอบการรันจะเรียกใช้ขั้นตอนการกำหนดค่าใหม่และการเปลี่ยนแปลงของเราถูกนำมาพิจารณาอย่างเต็มที่&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;อย่างไรก็ตาม นี่เป็นเพียงวิธีแก้ปัญหาชั่วคราว ไม่ใช่แนวทางแก้ไขที่ยั่งยืน มันลดประสิทธิภาพและไม่ได้แก้ปัญหาหลักของปลั๊กอินของเรา&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ทางออกที่แท้จริง_ทำให้ปลั๊กอินเข้ากันได้&quot;&gt;ทางออกที่แท้จริง: ทำให้ปลั๊กอินเข้ากันได้&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อให้ปลั๊กอินเป็นพลเมืองที่ดีของระบบนิเวศ Gradle สมัยใหม่ ปลั๊กอินนั้นต้องเข้ากันได้กับแคชการกำหนดค่า นี่หมายความว่าจำเป็นต้องทบทวนวิธีที่ข้อมูลไหลไปยังงานของเรา&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;คีย์คือการใช้&lt;strong&gt;ผู้ให้บริการ APIs&lt;/strong&gt;ของ Gradle. แทนที่จะส่งค่าโดยตรง (เช่น`String` ou un &lt;code&gt;File&lt;/code&gt;) ถึง ของเรา งาน, เรา ต้อง ใช้ บ้าง`Property&amp;lt;T&amp;gt;`หรือบาง`Provider&amp;lt;T&amp;gt;`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;นี่คือแผนการรีฟักทอริ่ง :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ระบุรายการงาน :&lt;/strong&gt;งานที่ทำการวิเคราะห์ไฟล์ YAML ต้องกำหนดให้ไฟล์นี้เป็นอินพุต เราใช้คำอธิบายประกอบสำหรับสิ่งนี้`@InputFile`.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] No text given for translation. Outputting empty.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;(Actually I need to output nothing.) I&amp;#8217;ll output an empty line. Since cannot include any characters? Might produce nothing. We&amp;#8217;ll send blank.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&amp;lt;/think&amp;gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;I’ll send nothing. @get:InputFile abstract val configFile: RegularFileProperty (empty)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ใช้งาน &lt;code&gt;Property&lt;/code&gt; และ &lt;code&gt;Provider&lt;/code&gt; :&lt;/strong&gt;ค่าของ`configFile`จะเชื่อมต่อกับทรัพย์สิน`configPath`จากส่วนขยาย DSL ของเรา. &lt;code&gt;Gradle&lt;/code&gt; สามารถติดตามต้นทางของข้อมูลได้&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] (no response) // ในปลั๊กอิน tasks.register&amp;lt;MyTask&amp;gt;(&quot;myTask&quot;) { configFile.set(extension.configPath.flatMap { project.layout.projectDirectory.file(it) }) } (empty)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;อ่านเนื้อหาในเวลาที่เหมาะสม :&lt;/strong&gt;การอ่านไฟล์ต้องทำภายในขั้นตอนของงาน`@TaskAction`) , โดยใช้`Provider`ของทางเข้า.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] (empty) @TaskAction ฟังก์ชัน execute() { val content = configFile.get().asFile.readText() // &amp;#8230;&amp;#8203; แยกและวิเคราะห์เนื้อหา } (Empty response)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตามรูปแบบนี้ Gradle เข้าใจว่าถ้าคอนเทนต์ของ`configFile`เปลี่ยนแปลง, แคชการตั้งค่าไม่ถูกต้องและขั้นตอนการตั้งค่าต้องทำใหม่. นอกจากนี้ยังรู้ว่าผลของงานขึ้นอยู่กับเนื้อหาของไฟล์นี้ ซึ่งยังช่วยให้สามารถเพิ่มประสิทธิภาพแคชการดำเนินการได้ด้วย.&lt;code&gt;UP-TO-DATE&lt;/code&gt;)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สรุป&quot;&gt;สรุป&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การผจญภัยในการแก้ไขข้อบกพร่องนี้เป็นบทเรียนที่มีค่า. พฤติกรรม &#39;เวทมนตร์&#39; ของแคชการกำหนดค่าบังคับให้เราเข้าใจวัฏจักรชีวิตของ Gradle และหลักการของการเขียนโปรแกรมแบบประกาศและลื่นไหลได้ดีขึ้น`lazy`).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ปิดการใช้งานแคชการกำหนดค่าเป็นเครื่องมือวินิจฉัยที่มีประโยชน์ แต่ทางออกที่แท้จริงคือการออกแบบปลั๊กอินที่แข็งแกร่งและทันสมัย. โดยการสร้างแบบจำลองอินพุตและเอาต์พุตของงานของเราอย่างถูกต้องด้วย API`Provider`, เราไม่ได้แก้เพียงแค่บั๊กเท่านั้น แต่ยังปรับปรุงประสิทธิภาพ ความน่าเชื่อถือ และความสามารถในการบำรุงรักษาปลั๊กอินของเรา&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในบทความต่อไป เราจะนำการรีฟักทอริงนี้ไปใช้งานจริง เพื่อให้การพาร์ส YAML ของเราสามารถทำงานได้อย่างเต็มประสิทธิภาพและเข้ากันได้อย่างสมบูรณ์กับแคชการตั้งค่า&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;สารบัญ&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_บทนำ&quot;&gt;บทนำ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_บริบท_ปลั๊กอินของเรา_site_baker&quot;&gt;บริบท : ปลั๊กอินของเรา `site-baker&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การสร้างแบบจำลองการตั้งค่าใน_kotlin&quot;&gt;การสร้างแบบจำลองการตั้งค่าใน Kotlin&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_การผสานรวม_jackson_ใน_build_gradle_kts&quot;&gt;3. การผสานรวม Jackson ใน `build.gradle.kts&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_วิธีการ_tdd_ทดสอบการวิเคราะห์_yaml&quot;&gt;4. วิธีการ TDD : ทดสอบการวิเคราะห์ YAML&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_ทดสอบหน่วย_แมป_yaml_เป็นออบเจกต์_kotlin&quot;&gt;4.1. ทดสอบหน่วย : แมป YAML เป็นออบเจกต์ Kotlin&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_ทดสอบการทำงาน_ตรวจสอบการอ่านไฟล์การตั้งค่า&quot;&gt;4.2. ทดสอบการทำงาน : ตรวจสอบการอ่านไฟล์การตั้งค่า&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_การแสดงผลของการไหลของการวิเคราะห์&quot;&gt;5. การแสดงผลของการไหลของการวิเคราะห์&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สรุป&quot;&gt;สรุป&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทนำ&quot;&gt;บทนำ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;กลุ่มเป้าหมาย : นักพัฒนา Gradle ระดับกลางที่ต้องการจัดการการตั้งค่าที่ซับซ้อน.&lt;/div&gt;
&lt;p&gt;ในการพัฒนาโปรเจ็กต์ปลั๊กอิน Gradle การจัดการการกำหนดค่าที่ซับซ้อนเป็นงานที่ทำบ่อย แทนที่จะทำให้ DSL เต็มไปด้วยหลายร้อยคุณสมบัติ มักจะดีและบำรุงรักษาง่ายขึ้นเมื่อกำหนดการตั้งค่าไว้ในไฟล์ภายนอก เช่น YAML บทความนี้แนะนำวิธีการผสานไลบรารีที่ทรงพลัง Jackson เพื่อแปลงไฟล์ YAML เป็นวัตถุ Kotlin โดยใช้แนวทาง TDD อย่างเข้มงวดเพื่อให้แน่ใจว่าปลั๊กอินของเรามีความแข็งแกร่ง`site-baker`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บริบท_ปลั๊กอินของเรา_site_baker&quot;&gt;บริบท : ปลั๊กอินของเรา `site-baker&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ปลั๊กอินของเรา`site-baker`ถูกออกแบบมาเพื่อให้ทำการสร้างและเผยแพร่เว็บไซต์แบบคงที่ได้อย่างอัตโนมัติ. จำเป็นต้องอ่านไฟล์กำหนดค่า YAML (&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) เพื่อรับข้อมูลต่าง ๆ เช่น เส้นทางของแหล่งที่มา จุดหมายในการปรับใช้ และรหัส Git&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การกำหนดค่า YAML ที่เราต้องการทำการวิเคราะห์มีลักษณะดังนี้:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;bake:
  srcPath: &quot;./site/jbake&quot;
  destDirPath: &quot;bake&quot;
  cname: &quot;cheroliv.com&quot;
pushPage:
  from: &quot;bake&quot;
  to: &quot;cvs&quot;
  repo:
    name: &quot;trainings&quot;
    repository: &quot;https://github.com/pages-content/pages-content.github.io.git&quot;
    credentials:
      username: &quot;USERNAME&quot;
      password: &quot;SECRET_TOKEN&quot;
  branch: &quot;main&quot;
  message: &quot;cheroliv.com&quot;
# ... autres configurations (pushMaquette, supabase, etc.)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การสร้างแบบจำลองการตั้งค่าใน_kotlin&quot;&gt;การสร้างแบบจำลองการตั้งค่าใน Kotlin&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ก่อนที่จะทำการพาร์ส เราต้องกำหนดโครงสร้างข้อมูลของเราในภาษา Kotlin ไว้ก่อน และแจ็คสันจะใช้คลาสเหล่านี้เพื่อแมปเนื้อหาของไฟล์ YAML ได้โดยอัตโนมัติ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/main/kotlin/com/cheroliv/site/baker/data/SiteConfiguration.kt
package com.cheroliv.site.baker.data

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory
import com.fasterxml.jackson.module.kotlin.readValue
import com.fasterxml.jackson.module.kotlin.registerKotlinModule

fun parseSiteConfiguration(yaml: String): SiteConfiguration {
    val mapper = ObjectMapper(YAMLFactory()).registerKotlinModule()
    return mapper.readValue(yaml)
}

data class GitPushConfiguration(
    val from: String = &quot;&quot;,
    val to: String = &quot;&quot;,
    val repo: RepositoryConfiguration = RepositoryConfiguration(),
    val branch: String = &quot;&quot;,
    val message: String = &quot;&quot;,
)

data class RepositoryConfiguration(
    val name: String = &quot;&quot;,
    val repository: String = &quot;&quot;,
    val credentials: RepositoryCredentials = RepositoryCredentials(),
) {
    companion object {
        const val ORIGIN = &quot;origin&quot;
        const val CNAME = &quot;CNAME&quot;
        const val REMOTE = &quot;remote&quot;
    }
}

data class RepositoryCredentials(val username: String = &quot;&quot;, val password: String = &quot;&quot;)

data class SiteConfiguration(
    val bake: BakeConfiguration = BakeConfiguration(),
    val pushPage: GitPushConfiguration = GitPushConfiguration(),
    val pushMaquette: GitPushConfiguration = GitPushConfiguration(),
    val pushSource: GitPushConfiguration? = null,
    val pushTemplate: GitPushConfiguration? = null,
    val supabase: SupabaseContactFormConfig? = null
)

data class BakeConfiguration(
    val srcPath: String = &quot;&quot;,
    val destDirPath: String = &quot;&quot;,
    val cname: String? = null,
)

// ... (autres data classes pour Supabase, si nécessaire)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ฟังก์ชัน`parseSiteConfiguration`เป็นจุดเริ่มต้นสำหรับการทำดีซีเรียลไลซ์ของเรา เธอใช้งาน`ObjectMapper`ของ Jackson, ที่กำหนดค่าโดยใช้`YAMLFactory`สำหรับรูปแบบ YAML และ`registerKotlinModule()`เพื่อการสนับสนุนคุณลักษณะเฉพาะของ Kotlin (เช่น ค่าเริ่มต้นของคุณสมบัติ).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_การผสานรวม_jackson_ใน_build_gradle_kts&quot;&gt;3. การผสานรวม Jackson ใน `build.gradle.kts&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อใช้งาน Jackson เราต้องเพิ่มการพึ่งพาที่จำเป็นลงใน`build.gradle.kts`ของโมดูลเรา`plugin`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/build.gradle.kts
dependencies {
    // Jackson for YAML parsing
    implementation(&quot;com.fasterxml.jackson.module:jackson-module-kotlin:2.18.3&quot;)
    implementation(&quot;com.fasterxml.jackson.dataformat:jackson-dataformat-yaml:2.18.3&quot;)

    // ... autres dépendances
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เราใช้`jackson-module-kotlin`เพื่อการสนับสนุน Kotlin และ`jackson-dataformat-yaml`เพื่อการจัดการรูปแบบ YAML&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_วิธีการ_tdd_ทดสอบการวิเคราะห์_yaml&quot;&gt;4. วิธีการ TDD : ทดสอบการวิเคราะห์ YAML&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตอนนี้เรามาใช้ TDD เพื่อตรวจสอบตรรกะการวิเคราะห์ของเรากันเถอะ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_ทดสอบหน่วย_แมป_yaml_เป็นออบเจกต์_kotlin&quot;&gt;4.1. ทดสอบหน่วย : แมป YAML เป็นออบเจกต์ Kotlin&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เราเริ่มต้นด้วยการทดสอบหน่วยใน`SiteBakerPluginTest.kt`เพื่อตรวจสอบว่าฟังก์ชั่น`parseSiteConfiguration`สามารถแปลงสตริง YAML เป็นวัตถุได้อย่างถูกต้อง`SiteConfiguration`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/test/kotlin/com/cheroliv/site/baker/SiteBakerPluginTest.kt
@Test
fun `can map configuration text to SiteConfiguration object`() {
    val yamlString = &quot;../../managed-jbake-context.yml&quot;
        .run(::File)
        .readText()
        .trimIndent()

    val config: SiteConfiguration = parseSiteConfiguration(yamlString)

    assertEquals(&quot;cheroliv.com&quot;, config.bake.cname)
    assertEquals(&quot;main&quot;, config.pushPage.branch)
    assertEquals(&quot;https://github.com/pages-content/pages-content.github.io.git&quot;, config.pushPage.repo.repository)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทดสอบนี้อ่านเนื้อหาของไฟล์`managed-jbake-context.yml`(ซึ่งจำเป็นต้องมีเพื่อให้การทดสอบเป็นที่ใช้ได้) และทำการยืนยันกับวัตถุนี้`SiteConfiguration`เป็นผลลัพธ์ที่ได้. ตรวจสอบว่าค่าคีย์ใน YAML นั้นถูกแมปอย่างถูกต้อง。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_ทดสอบการทำงาน_ตรวจสอบการอ่านไฟล์การตั้งค่า&quot;&gt;4.2. ทดสอบการทำงาน : ตรวจสอบการอ่านไฟล์การตั้งค่า&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อให้แน่ใจว่าปลั๊กอินสามารถอ่านไฟล์การกำหนดค่าโดยใช้ DSL ของมันและการวิเคราะห์ทำงานในสภาพแวดล้อม Gradle จริง เราจึงเพิ่มการทดสอบฟังก์ชันลงใน`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทดสอบนี้มีความสำคัญเนื่องจากมันจำลองการดำเนินการของปลั๊กอินในโครงการจริง มันต้องเป็น&lt;strong&gt;ปิดสนิท&lt;/strong&gt;, กล่าวคือ เขาต้องสร้างไฟล์นี้ด้วยตัวเอง`managed-jbake-context.yml`ด้วยเนื้อหาที่ควบคุมไว้ เพื่อรับประกันความสามารถในการทำซ้ำและการแยกส่วนของการทดสอบ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/functionalTest/kotlin/com/cheroliv/site/baker/SiteBakerPluginFunctionalTest.kt
@Test
fun `config file contains good data`(){
    val configContent = configFile.readText(UTF_8)
    // Vérifications comme dans vos commentaires
    assertTrue(configContent.contains(&quot;bake&quot;))
    assertTrue(configContent.contains(&quot;pushPage&quot;))
    assertTrue(configContent.contains(&quot;repository&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทดสอบเชิงฟังก์ชันนี้ตรวจสอบว่า ไฟล์การกำหนดค่าที่ถูกคัดลอกไปยังโฟลเดอร์ชั่วคราวของการทดสอบ มีข้อมูลตามที่คาดหวัง. แม้ว่าการทดสอบนี้จะไม่ได้วิเคราะห์ YAML เป็นวัตถุ Kotlin โดยตรง แต่จะตรวจสอบความมีอยู่ของไฟล์และเนื้อหา ซึ่งเป็นขั้นตอนเบื้องต้นที่จำเป็นต่อการทำการวิเคราะห์โดยปลั๊กอิน&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_การแสดงผลของการไหลของการวิเคราะห์&quot;&gt;5. การแสดงผลของการไหลของการวิเคราะห์&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;แผนภาพต่อไปนี้แสดงให้เห็นการไหลของข้อมูลและปฏิสัมพันธ์ระหว่างการวิเคราะห์คอนฟิกูเรชัน YAML:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;diag-plantuml-md5-66df6a722798cccd8faea74f6f2e21b3.png&quot; alt=&quot;Diagram&quot; width=&quot;1445&quot; height=&quot;472&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สรุป&quot;&gt;สรุป&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ด้วยการปฏิบัติตามแนวทาง TDD เราได้บูรณาการไลบรารี Jackson เพื่อทำการพาร์สไฟล์การกำหนดค่า YAML เป็นอ็อบเจ็กต์ Kotlin ในปลั๊กอิน Gradle ของเราอย่างสำเร็จ. วิธีนี้ทำให้เราสามารถ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ทำการสร้างแบบจำลองอย่างชัดเจน&lt;/strong&gt;การตั้งค่าของเราด้วยคลาส data ของ Kotlin&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ตรวจสอบตรรกะของการพาร์ซ&lt;/strong&gt;ด้วยการทดสอบหน่วยที่เฉพาะเจาะจง.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;รับประกันการบูรณาการ&lt;/strong&gt;ในสภาพแวดล้อม Gradle จริงๆ ผ่านการทดสอบเชิงฟังก์ชันที่เป็นเฮอร์เมติก&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ฐานที่มั่นคงนี้ทำให้เรามีความมั่นใจอย่างยิ่งในการขยายปลั๊กอินของเราด้วยฟีเจอร์ต่างๆ ที่พึ่งพาการตั้งค่านี้ พร้อมทั้งรับประกันความสามารถในการบำรุงรักษาและความแข็งแกร่งของโค้ด การวิเคราะห์ YAML ได้กลายเป็นฟีเจอร์ที่เชื่อถือได้และได้รับการทดสอบแล้วของปลั๊กอินของเรา`site-baker`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_การเริ่มต้นโครงการ&quot;&gt;การเริ่มต้นโครงการ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_วัฏจักร_tdd_ครั้งแรกของเรา_บันทึกงานหนึ่งรายการ&quot;&gt;2. วัฏจักร TDD ครั้งแรกของเรา: บันทึกงานหนึ่งรายการ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_2_1_การทดสอบครั้งแรก_การทดสอบที่ล้มเหลว&quot;&gt;2.1. การทดสอบครั้งแรก (การทดสอบที่ล้มเหลว)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_2_โค้ดต่อไป_ทำให้การทดสอบผ่าน&quot;&gt;2.2. โค้ดต่อไป (ทำให้การทดสอบผ่าน)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_รอบที่สองของ_tdd_เพิ่มส่วนขยาย_dsl&quot;&gt;3. รอบที่สองของ TDD: เพิ่มส่วนขยาย DSL&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_3_1_การทดสอบครั้งแรก&quot;&gt;3.1. การทดสอบครั้งแรก&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_2_รหัสต่อไป&quot;&gt;3.2. รหัสต่อไป&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_การทดสอบการทำงาน_ตรวจสอบการบูรณาการ&quot;&gt;4. การทดสอบการทำงาน: ตรวจสอบการบูรณาการ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_การทดสอบการบูรณาการ_สร้างสภาพแวดล้อมที่ควบคุมได้&quot;&gt;4.1. การทดสอบการบูรณาการ: สร้างสภาพแวดล้อมที่ควบคุมได้&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_ทำให้ลอจิกเสร็จสมบูรณ์&quot;&gt;4.2. ทำให้ลอจิกเสร็จสมบูรณ์&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สรุป&quot;&gt;สรุป&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในบทความนี้ เราจะสำรวจวิธีการตั้งค่าพื้นฐานการพัฒนาที่แข็งแรงสำหรับปลั๊กอิน Gradle โดยใช้แนวทางการพัฒนาที่ขับเคลื่อนด้วยการทดสอบ (TDD - Test-Driven Development) วิธีนี้ทำให้มั่นใจได้ว่าโค้ดของเราจะมีความแข็งแรง สามารถบำรุงรักษาได้ และตรงตามความต้องการอย่างแม่นยำตั้งแต่ต้น&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การเริ่มต้นโครงการ&quot;&gt;การเริ่มต้นโครงการ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle ทำให้การสร้างปลั๊กอินใหม่เป็นเรื่องง่ายขึ้นอย่างมากด้วยคำสั่ง`gradle init`. โดยการเลือกที่จะสร้าง &quot;Gradle Plugin&quot; ด้วย Kotlin เราจะได้โครงสร้างโปรเจ็กต์ที่พร้อมใช้งาน ซึ่งรวมถึงการทดสอบที่สำคัญสองประเภท:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;การทดสอบหน่วย :&lt;/strong&gt;ตั้งอยู่ใน`src/test`, พวกเขาสามารถใช้ตรวจสอบคอมโพเนนต์ที่แยกออกของปลั๊กอินของเราได้ เช่น ตรรกะภายในของงานหรือการตั้งค่าของส่วนขยาย พวกเขาทำได้รวดเร็วและไม่จำเป็นต้องทำการรัน Gradle เต็มรูปแบบ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;การทดสอบฟังก์ชัน :&lt;/strong&gt;ตั้งอยู่ใน`src/functionalTest`, พวกเขาใช้`GradleRunner`เพื่อทำการสร้าง Gradle เต็มรูปแบบในโครงการทดลองชั่วคราวของเรา นี่จะช่วยให้เราตรวจสอบพฤติกรรมที่เป็นจริงของปลั๊กอินในสภาพแวดล้อมที่มีการควบคุม&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_วัฏจักร_tdd_ครั้งแรกของเรา_บันทึกงานหนึ่งรายการ&quot;&gt;2. วัฏจักร TDD ครั้งแรกของเรา: บันทึกงานหนึ่งรายการ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ความต้องการแรกของเราเป็นเรื่องง่าย: ปลั๊กอินต้องบันทึกงานที่ชื่อว่า`printSiteConfig`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_1_การทดสอบครั้งแรก_การทดสอบที่ล้มเหลว&quot;&gt;2.1. การทดสอบครั้งแรก (การทดสอบที่ล้มเหลว)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตามหลักการของ TDD เราเขียนทดสอบก่อนเพื่อตรวจสอบว่ามีงานนี้อยู่จริง. ใน`SiteBakerPluginTest.kt`(ไฟล์ทดสอบหน่วยของเรา), เราเพิ่ม :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers task`() {
    // Créer un projet de test en mémoire
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Vérifier que la tâche a bien été enregistrée
    assertNotNull(project.tasks.findByName(&quot;printSiteConfig&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทดสอบนี้ล้มเหลว เพราะเรายังไม่ได้เขียนโค้ดใดๆ ในปลั๊กอินของเรา&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_2_โค้ดต่อไป_ทำให้การทดสอบผ่าน&quot;&gt;2.2. โค้ดต่อไป (ทำให้การทดสอบผ่าน)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตอนนี้เราเขียนโค้ดขั้นต่ำที่จำเป็นใน`SiteBakerPlugin.kt`เพื่อให้การทดสอบผ่าน :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer une tâche simple
        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            // ... la logique de la tâche viendra plus tard
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เราทำการรีสตาร์ทการทดสอบและพวกมันผ่านไปแล้ว ฟังก์ชั่นแรกของเราได้รับการตรวจสอบและอนุมัติเรียบร้อยแล้ว.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_รอบที่สองของ_tdd_เพิ่มส่วนขยาย_dsl&quot;&gt;3. รอบที่สองของ TDD: เพิ่มส่วนขยาย DSL&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ความต้องการต่อไปคือการอนุญาตให้ผู้ใช้กำหนดค่าปลั๊กอินของเราผ่านบล็อก DSL ในของพวกเขา`build.gradle.kts`. เราต้องการบล็อก`site { &amp;#8230;&amp;#8203; }`ที่สามารถระบุเส้นทางการกำหนดค่าได้&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_1_การทดสอบครั้งแรก&quot;&gt;3.1. การทดสอบครั้งแรก&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพิ่มการทดสอบเพื่อตรวจสอบว่าส่วนขยายนี้`site`ได้บันทึกไว้อย่างดีและเราสามารถกำหนดค่าให้กับมันได้.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers extension`() {
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Récupérer l&#39;extension et lui affecter une valeur
    project.extensions
        .findByType(SiteExtension::class.java)!!
        .configPath
        .set(&quot;config.yml&quot;)

    // Vérifier que la valeur a bien été prise en compte
    assertEquals(
        &quot;config.yml&quot;,
        project.extensions.findByType(SiteExtension::class.java)?.configPath?.get()
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทดสอบนี้ล้มเหลวเพราะไม่ใช่คลาส`SiteExtension`และการลงทะเบียนของส่วนขยายนี้ก็ไม่ได้มีอยู่&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_2_รหัสต่อไป&quot;&gt;3.2. รหัสต่อไป&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เรากำลังสร้างคลาส`SiteBakerExtension.kt`และเราอัปเดต`SiteBakerPlugin.kt`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// SiteBakerExtension.kt
open class SiteExtension @Inject constructor(objects: ObjectFactory) {
    val configPath: Property&amp;lt;String&amp;gt; = objects.property(String::class.java)
}

// SiteBakerPlugin.kt
class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer l&#39;extension
        val extension = project.extensions.create(&quot;site&quot;, SiteExtension::class.java)

        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            task.doLast {
                // On utilisera l&#39;extension plus tard
            }
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทดสอบผ่านอีกครั้ง&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_การทดสอบการทำงาน_ตรวจสอบการบูรณาการ&quot;&gt;4. การทดสอบการทำงาน: ตรวจสอบการบูรณาการ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;หลังจากที่หน่วยผ่านการทดสอบแล้ว เราต้องตรวจสอบให้แน่ใจว่าทุกอย่างทำงานร่วมกันในบิลด์จริงๆ. นี่เป็นบทบาทของการทดสอบฟังก์ชันใน`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_การทดสอบการบูรณาการ_สร้างสภาพแวดล้อมที่ควบคุมได้&quot;&gt;4.1. การทดสอบการบูรณาการ: สร้างสภาพแวดล้อมที่ควบคุมได้&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทดสอบนี้จะจำลองโครงการจริงโดยใช้ปลั๊กอินของเรา เพื่อให้มันเชื่อถือได้ มันต้องเป็น&lt;strong&gt;กันอากาศ&lt;/strong&gt;, นั่นคือมันจะต้องไม่ขึ้นต่อไฟล์ที่มีอยู่ในระบบ และมันต้องสร้างเงื่อนไขที่จำเป็นทั้งหมดด้วยตัวเองก่อนที่จะทำงาน&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทดสอบจึง :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;สร้าง`build.gradle.kts`ไฟล์ทดสอบที่ใช้ปลั๊กอินของเราและ DSL ของมัน&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;สร้างไฟล์กำหนดค่า&lt;/strong&gt;(&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) ที่ปลั๊กอินควรจะอ่าน. นี่เป็นขั้นตอนที่สำคัญสำหรับความเสถียรของการทดสอบ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ดำเนินการงาน`printSiteConfig`ผ่าน`GradleRunner`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ตรวจสอบว่าผลลัพธ์ของการสร้างเป็นไปอย่างถูกต้อง&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การคัดลอกหรือสร้างไฟล์การกำหนดค่านี้ในแต่ละครั้งที่ทำงาน เราจะมั่นใจว่าการทดสอบ&lt;strong&gt;สามารถทำซ้ำได้&lt;/strong&gt;และไม่ขึ้นอยู่กับสถานะภายนอก. ซึ่งทำให้การทดสอบของเราปลอดภัยจากการถดถอยที่อาจเชื่อมโยงกับการอ่านไฟล์&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test fun `can run task with DSL`() {
    // 1. Créer un build.gradle.kts de test
    buildFile.writeText(&quot;&quot;&quot;
        plugins { id(&quot;com.cheroliv.site-baker&quot;) }
        site { configPath = &quot;managed-jbake-context.yml&quot; }
    &quot;&quot;&quot;.trimIndent())

    // 2. Créer le fichier de configuration pour un test contrôlé
    val configFile = File(projectDir, &quot;managed-jbake-context.yml&quot;)
    configFile.writeText(&quot;site: { title: &#39;Mon Site de Test&#39; }&quot;) // Contenu YAML simple

    // 3. Exécuter la build
    val runner = GradleRunner.create()
    runner.withPluginClasspath()
    runner.withArguments(&quot;printSiteConfig&quot;)
    runner.withProjectDir(projectDir) // Spécifier le répertoire du projet de test
    val result = runner.build()

    // 4. Vérifier la sortie
    assertTrue(result.output.contains(&quot;Site config path: managed-jbake-context.yml&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การทดสอบนี้จะล้มเหลวตราบใดที่งาน`printSiteConfig`มันจะไม่ใช้ค่าของส่วนขยายนี้จริงๆ&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_ทำให้ลอจิกเสร็จสมบูรณ์&quot;&gt;4.2. ทำให้ลอจิกเสร็จสมบูรณ์&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;พวกเรากำลังอัปเดตงานอยู่ภายใน`SiteBakerPlugin.kt`เพื่อให้แสดงค่าที่ตั้งค่าไว้:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
    task.doLast {
        println(&quot;Site config path: ${extension.configPath.get()}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตอนนี้การทดสอบทั้งแบบหน่วยและฟังก์ชัน ผ่านทั้งหมดแล้ว&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สรุป&quot;&gt;สรุป&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;โดยการทำตามแนวทาง TDD เราได้สร้างปลั๊กอินอย่างเป็นขั้นตอนและปลอดภัย ฟังก์ชันเล็ก ๆ ทุกฟังก์ชันจะได้รับการตรวจสอบทันทีโดยการทดสอบ ตั้งแต่การทดสอบหน่วยที่รวดเร็วไปจนถึงการทดสอบเชิงฟังก์ชันที่ตรวจสอบการบูรณาการอย่างสมบูรณ์&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;โดยดูแลให้การทดสอบของเราทำงานได้&lt;strong&gt;ปิดผนึก&lt;/strong&gt;— โดยเฉพาะในการสร้างไฟล์การตั้งค่าที่จำเป็นโดยทางโปรแกรม — เราสร้างตาข่ายความปลอดภัยที่แข็งแกร่งอย่างยิ่ง. ความเข้มงวดนี้ปกป้องเราได้อย่างมีประสิทธิภาพจากการถดถอยและทำให้เรามีความเชื่อมั่นอย่างมากในการเพิ่มฟังก์ชันที่ซับซ้อนยิ่งขึ้นต่อไป เช่น การวิเคราะห์ไฟล์การตั้งค่า YAML&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ฐานการทดสอบที่เข้มแข็งนี้คือสินทรัพย์ที่มีค่าที่สุดสำหรับการบำรุงและการพัฒนาเพิ่มเติมของปลั๊กอินในอนาคต&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;สารบัญ&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_บทนำ&quot;&gt;บทนำ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ขั้นตอนที่_1_เปิดตัวช่วยโครงการ&quot;&gt;ขั้นตอนที่ 1: เปิดตัวช่วยโครงการ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ขั้นตอนที่_2_ทำความเข้าใจโครงสร้างที่สร้างขึ้น&quot;&gt;ขั้นตอนที่ 2: ทำความเข้าใจโครงสร้างที่สร้างขึ้น&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ไฟล์และโฟลเดอร์หลัก&quot;&gt;ไฟล์และโฟลเดอร์หลัก&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ขั้นตอนที่_3_สร้างและทดสอบปลั๊กอิน&quot;&gt;ขั้นตอนที่ 3 : สร้างและทดสอบปลั๊กอิน&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_งานพื้นฐาน&quot;&gt;งานพื้นฐาน&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สรุป&quot;&gt;สรุป&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทนำ&quot;&gt;บทนำ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;กลุ่มเป้าหมาย : นักพัฒนาเริ่มต้นถึงระดับกลางที่ใช้ Gradle.&lt;/div&gt;
&lt;p&gt;การเริ่มต้นโปรเจกต์ปลั๊กอิน Gradle ใหม่ อาจดูน่ากลัว. ดีที่ Gradle มีผู้ช่วยแบบโต้ตอบที่ทรงพลัง, งาน`init`, ซึ่งจะสร้างโครงสร้างโปรเจ็กต์ที่สมบูรณ์ สะอาด พร้อมใช้งาน คู่มือนี้จะแสดงวิธีการใช้เครื่องมือนี้เพื่อสร้างฐานปลั๊กอินที่ดี อธิบายโครงสร้างและแสดงให้เห็นวิธีเรียกใช้งานงานบิลด์แรก.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ขั้นตอนที่_1_เปิดตัวช่วยโครงการ&quot;&gt;ขั้นตอนที่ 1: เปิดตัวช่วยโครงการ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;คำสั่ง`gradle init`เป็นจุดเริ่มต้น. มันเปิดใช้งานผู้ช่วยบรรทัดคำสั่งออนไลน์ซึ่งถามคุณชุดคำถามเพื่อตั้งค่าโครงการ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เปิดเทอร์มินัลของคุณในโฟลเดอร์ว่างและรัน :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle init&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ผู้ช่วยจะแนะนำคุณ นี่คือตัวเลือกที่ต้องทำสำหรับปลั๊กอิน Gradle ที่เขียนด้วย Kotlin :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;เลือกประเภทโครงการที่จะสร้าง:&lt;/strong&gt;เลือก`Gradle plugin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;เลือกภาษาที่จะใช้ในการทำงาน:&lt;/strong&gt;เลือก`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;เลือกสคริปต์การสร้าง DSL:&lt;/strong&gt;เลือก`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ชื่อโครงการ:&lt;/strong&gt;ใส่ชื่อสำหรับโครงการของคุณ (ตัวอย่าง:`site-baker`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;รหัสปลั๊กอิน:&lt;/strong&gt;กำหนดไอดีที่ไม่ซ้ำกันให้กับปลั๊กอินของคุณ (เช่น`com.cheroliv.site-baker`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;คลาสปลั๊กอิน:&lt;/strong&gt;ระบุชื่อคลาสของการดำเนินการ (เช่น`com.cheroliv.SiteBakerPlugin`).&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เมื่อเสร็จสิ้นแล้ว Gradle จะสร้างโครงสร้างไฟล์ที่สมบูรณ์&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;init-gradle.svg&quot; alt=&quot;init gradle&quot; width=&quot;199&quot; height=&quot;406&quot;&gt;
&lt;/div&gt;
&lt;div class=&quot;title&quot;&gt;Figure 1. แผนภาพกระบวนการเริ่มต้น&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ขั้นตอนที่_2_ทำความเข้าใจโครงสร้างที่สร้างขึ้น&quot;&gt;ขั้นตอนที่ 2: ทำความเข้าใจโครงสร้างที่สร้างขึ้น&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ผู้ช่วยสร้างโครงสร้างโปรเจ็กต์แบบหลายโมดูล โดยแยกโปรเจ็กต์หลักออกจากซอร์สโค้ดของปลั๊กอินตัวเอง&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;.
├── gradle/
│   └── wrapper/
│       ├── gradle-wrapper.jar
│       └── gradle-wrapper.properties
├── gradlew
├── gradlew.bat
├── plugin/
│   ├── build.gradle.kts
│   └── src/
│       ├── main/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPlugin.kt
│       ├── test/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPluginTest.kt
│       └── functionalTest/
│           └── kotlin/
│               └── com/cheroliv/SiteBakerPluginFunctionalTest.kt
└── settings.gradle.kts&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ไฟล์และโฟลเดอร์หลัก&quot;&gt;ไฟล์และโฟลเดอร์หลัก&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;settings.gradle.kts`ไฟล์นี้ในรากกำหนดโมดูลที่รวมอยู่ในบิลด์ อย่างนี้จะรวมซับโปรเจกต์ของโครงการ`plugin&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[แหล่งที่มา,kotlin] ---- rootProject.name = &quot;site-baker include(&quot;plugin&quot;) ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;plugin/build.gradle.kts`นี่คือแกนหลักของการตั้งค่าปลั๊กอินของคุณ. มันประยุกต์ใช้ปลั๊กอิน`java-gradle-plugin&lt;/code&gt;, ประกาศความต้องการส่วนเสริมและกำหนดค่าเมตาดาต้าของปลั๊กอิน&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] ---- ปลั๊กอิน { &lt;code&gt;java-gradle-plugin&lt;/code&gt; alias(libs.plugins.kotlin.jvm) }&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;gradlePlugin { val siteBaker by plugins.creating { id = &quot;com.cheroliv.site-baker implementationClass = &quot;com.cheroliv.SiteBakerPlugin } } ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;`src/main/`มีซอร์สโค้ดของปลั๊กอินของคุณ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;`src/test/`มีการทดสอบหน่วยอยู่ที่นี่ ซึ่งทำงานได้อย่างรวดเร็วและเป็นอิสระต่อกัน&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;`src/functionalTest/`มีการทดสอบฟังก์ชัน. การทดสอบเหล่านี้ใช้`GradleRunner`เพื่อทำการรันเวอร์ชั่นเต็มของ Gradle ในโปรเจ็กต์ทดสอบ โดยจำลองการใช้งานจริงของปลั๊กอินของคุณ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ขั้นตอนที่_3_สร้างและทดสอบปลั๊กอิน&quot;&gt;ขั้นตอนที่ 3 : สร้างและทดสอบปลั๊กอิน&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;โครงการที่สร้างขึ้นนี้รวมถึง&lt;strong&gt;Gradle Wrapper&lt;/strong&gt; (&lt;code&gt;gradlew&lt;/code&gt;). นี่คือวิธีที่แนะนำในการรัน Gradle, เพราะมันรับประกันว่านักพัฒนาทุกคนใช้เวอร์ชันเดียวกัน, ทำให้การสร้างผลลัพธ์สามารถทำซ้ำได้&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_งานพื้นฐาน&quot;&gt;งานพื้นฐาน&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;สร้างโครงการ :&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;คำสั่งนี้จะทำการคอมไพล์โค้ดของคุณ, เรียกใช้การทดสอบทั้งหมด (หน่วยและฟังก์ชัน) และประกอบ JAR ของปลั๊กอินของคุณ (No output because there is no provided French text.) ---- ./gradlew build (Empty)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ทำการตรวจสอบทั้งหมด :&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;งาน`check`เป็นนามแฝงที่ทำหน้าที่ดำเนินการงานตรวจสอบทั้งหมด, รวมถึง`test` et &lt;code&gt;functionalTest&lt;/code&gt;. [source,bash] ---- ./gradlew ตรวจสอบ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;เรียกใช้เฉพาะการทดสอบหน่วยเท่านั้น :&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อรับฟีดแบ็กที่รวดเร็วขณะทำการพัฒนา [แหล่งที่มา,bash] (No text) ./gradlew test Could you please provide the French text you’d like translated into Thai?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;คำสั่ง`./gradlew :test`, ที่ระบุเป้าหมายอย่างชัดเจนสำหรับโปรเจกต์ราก, จะล้มเหลว เนื่องจากมันไม่มีการทดสอบเลย ในทางตรงกันข้าม:
*   &lt;code&gt;./gradlew test`ทำงานเพราะ Gradle รับผิดชอบในการทำงานของ Task`test`บนทุกๆ โครงการย่อยที่มันมีอยู่ (ที่นี่, โมดูล`plugin&lt;/code&gt;).
*   `./gradlew :plugin:test`เป็นคำสั่งที่ชัดเจนที่สุดในการเรียกใช้การทดสอบของโมดูล`plugin`เท่านั้น.&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;รันเฉพาะการทดสอบฟังก์ชัน :&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ส่วนที่ช้ากว่านั้น มีประโยชน์ในการตรวจสอบพฤติกรรมโดยรวม [source,bash] [No text provided to translate] ./gradlew functionalTest ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ผลลัพธ์ของการทดสอบถูกสร้างขึ้นในโฟลเดอร์`plugin/build/reports/tests/`. คุณสามารถเปิดไฟล์ได้`index.html`ในเบราว์เซอร์ของคุณเพื่อรายงานโดยละเอียด。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สรุป&quot;&gt;สรุป&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ภายในไม่กี่นาที,`gradle init`คุณได้รับฐานโครงการที่แข็งแรง ทันสมัย และสมบูรณ์สำหรับการพัฒนาปลั๊กอินของคุณ คุณมีโครงสร้างที่ชัดเจน มีการทดสอบหน่วยและฟังก์ชันที่กำหนดค่าล่วงหน้าแล้ว รวมถึงระบบการสร้างที่สามารถทำซ้ำได้ด้วย Gradle Wrapper&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;คุณพร้อมที่จะเปิดไฟล์แล้ว`SiteBakerPlugin.kt`และเริ่มเพิ่มตรรกะทางธุรกิจของปลั๊กอินของคุณลงไปในนั้น !&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;สารบัญ&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_บทนำ&quot;&gt;บทนำ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_jdk_เอนจินของ_gradle&quot;&gt;1. JDK : เอนจินของ Gradle&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_เลือกเวอร์ชันไหนดี&quot;&gt;เลือกเวอร์ชันไหนดี&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ติดตั้งผ่าน_sdkman_แนะนำ&quot;&gt;ติดตั้งผ่าน SDKMAN! (แนะนำ)&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ติดตั้ง_sdkman&quot;&gt;&lt;strong&gt;ติดตั้ง SDKMAN!&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ติดตั้งเวอร์ชันหนึ่งของ_jdk&quot;&gt;ติดตั้งเวอร์ชันหนึ่งของ JDK&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ตรวจสอบการติดตั้ง&quot;&gt;&lt;strong&gt;ตรวจสอบการติดตั้ง&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_ide_intellij_idea&quot;&gt;2. IDE : IntelliJ IDEA&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_gradle_เครื่องมือสำหรับ_build&quot;&gt;3. Gradle : เครื่องมือสำหรับ build&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_การติดตั้งผ่าน_sdkman&quot;&gt;การติดตั้งผ่าน SDKMAN!&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ติดตั้ง_gradle&quot;&gt;ติดตั้ง Gradle&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ตรวจสอบการติดตั้ง_2&quot;&gt;ตรวจสอบการติดตั้ง&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_jbake_เครื่องมือสร้างเว็บไซต์แบบสแตติก&quot;&gt;4. JBake : เครื่องมือสร้างเว็บไซต์แบบสแตติก&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_การติดตั้งผ่าน_sdkman_2&quot;&gt;การติดตั้งผ่าน SDKMAN!&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ติดตั้ง_jbake&quot;&gt;&lt;strong&gt;ติดตั้ง &lt;code&gt;JBake&lt;/code&gt;&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ตรวจสอบการติดตั้ง_3&quot;&gt;&lt;strong&gt;ตรวจสอบการติดตั้ง&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_gradle_wrapper_แนวปฏิบัติที่ดีที่สุดอย่างแท้จริง&quot;&gt;5. Gradle Wrapper : แนวปฏิบัติที่ดีที่สุดอย่างแท้จริง&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_6_docker_และ_portainer_สำหรับการบิลด์ที่ทำซ้ำได้_ไม่บังคับ&quot;&gt;6. Docker และ Portainer : สำหรับการบิลด์ที่ทำซ้ำได้ (ไม่บังคับ)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_การติดตั้ง_docker_engine&quot;&gt;การติดตั้ง Docker Engine&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ติดตั้ง_docker_ผ่านสคริปต์อย่างเป็นทางการ&quot;&gt;&lt;strong&gt;ติดตั้ง Docker ผ่านสคริปต์อย่างเป็นทางการ:&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_จัดการ_docker_โดยไม่ใช้_sudo_แนะนำ&quot;&gt;&lt;strong&gt;จัดการ Docker โดยไม่ใช้ &lt;code&gt;sudo&lt;/code&gt; (แนะนำ):&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_จัดการ_docker_ด้วย_portainer_gui&quot;&gt;จัดการ Docker ด้วย Portainer (GUI)&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_สร้างโวลุ่มสำหรับข้อมูลของ_portainer&quot;&gt;&lt;strong&gt;สร้างโวลุ่มสำหรับข้อมูลของ Portainer :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_เริ่มคอนเทนเนอร์_portainer&quot;&gt;&lt;strong&gt;เริ่มคอนเทนเนอร์ Portainer:&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_บทสรุป&quot;&gt;บทสรุป&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทนำ&quot;&gt;บทนำ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;กลุ่มเป้าหมาย: นักพัฒนาที่ต้องการเริ่มต้นสร้างปลั๊กอิน Gradle&lt;/div&gt;
&lt;p&gt;เพื่อพัฒนา Gradle plugins ได้อย่างมีประสิทธิภาพ จำเป็นอย่างยิ่งต้องมีสภาพแวดล้อมการพัฒนาที่ได้รับการกำหนดค่าอย่างดี เซ็ตอัปที่ดีจะช่วยให้คุณประหยัดเวลา ลดความหงุดหงิด และรับประกันความสม่ำเสมอของบิลด์ของคุณ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;คู่มือนี้มุ่งเน้นไปที่สี่เสาหลักที่สำคัญ:&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Le &lt;strong&gt;JDK&lt;/strong&gt;(Java Development Kit) เพราะ Gradle และ JBake ทำงานบน JVM&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Un &lt;strong&gt;ไอดีอี&lt;/strong&gt;ที่ทันสมัย (IntelliJ IDEA) พร้อมรองรับ Kotlin และ Gradle ได้เป็นอย่างดี&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Gradle&lt;/strong&gt;ตัวเขาเอง เพื่อเริ่มต้นโครงการ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;JBake&lt;/strong&gt;, เอนจินของเว็บไซต์สแตติกของเรา&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/gradle-env.svg&quot; alt=&quot;gradle env&quot; width=&quot;508&quot; height=&quot;213&quot;&gt;
&lt;/div&gt;
&lt;div class=&quot;title&quot;&gt;Figure 1. องค์ประกอบของสภาพแวดล้อมการพัฒนา&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_jdk_เอนจินของ_gradle&quot;&gt;1. JDK : เอนจินของ Gradle&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle เป็นแอปพลิเคชันที่ทำงานบน Java Virtual Machine (JVM) ดังนั้น การติดตั้ง JDK จึงเป็นข้อกำหนดเบื้องต้นที่จำเป็นอย่างยิ่ง&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_เลือกเวอร์ชันไหนดี&quot;&gt;เลือกเวอร์ชันไหนดี&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;แนะนำให้ใช้เวอร์ชัน LTS (Long-Term Support) ของ Java ในปัจจุบันนี้&lt;strong&gt;JDK 17&lt;/strong&gt; ou &lt;strong&gt;JDK 21&lt;/strong&gt;เป็นตัวเลือกที่ยอดเยี่ยม&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ติดตั้งผ่าน_sdkman_แนะนำ&quot;&gt;ติดตั้งผ่าน SDKMAN! (แนะนำ)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;SDKMAN! เป็นเครื่องมือที่ยอดเยี่ยมสำหรับจัดการเวอร์ชันของ SDK จำนวนมาก รวมถึง Java และ Gradle&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ติดตั้ง_sdkman&quot;&gt;&lt;strong&gt;ติดตั้ง SDKMAN!&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -s &quot;https://get.sdkman.io&quot; | bash source &quot;$HOME/.sdkman/bin/sdkman-init.sh&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ติดตั้งเวอร์ชันหนึ่งของ_jdk&quot;&gt;ติดตั้งเวอร์ชันหนึ่งของ JDK&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Pour lister les versions de Java disponibles sdk list java

# Pour installer Java 17 (par exemple, la distribution Temurin)
sdk install java 17.0.8-tem&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ตรวจสอบการติดตั้ง&quot;&gt;&lt;strong&gt;ตรวจสอบการติดตั้ง&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;java -version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;คุณควรเห็นเวอร์ชันที่คุณเพิ่งติดตั้งแสดงขึ้นมา&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_ide_intellij_idea&quot;&gt;2. IDE : IntelliJ IDEA&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สำหรับการพัฒนา Gradle plugin ด้วย Kotlin DSL,&lt;strong&gt;IntelliJ IDEA&lt;/strong&gt;เป็นเครื่องมือที่เลือกใช้ การผสานรวมของมันกับ Gradle และ Kotlin นั้นไม่มีใครเทียบได้&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ฉบับชุมชน :&lt;/strong&gt;ฟรีและเพียงพออย่างมากสำหรับการเริ่มต้น&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;อัลติเมทเอ็ดดิชัน :&lt;/strong&gt;เป็นบริการแบบเสียค่าใช้จ่าย และมีฟีเจอร์ขั้นสูงสำหรับการพัฒนาเว็บและฐานข้อมูล&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ดาวน์โหลดเวอร์ชันที่เหมาะกับคุณได้จากเว็บไซต์ของ JetBrains: &lt;a href=&quot;https://www.jetbrains.com/idea/download/&quot; class=&quot;bare&quot;&gt;https://www.jetbrains.com/idea/download/&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;IDE จะตรวจจับไฟล์ของคุณโดยอัตโนมัติ`build.gradle.kts` et &lt;code&gt;settings.gradle.kts&lt;/code&gt;, มอบการเติมข้อความอัตโนมัติอันทรงพลัง การนำทางโค้ด และเครื่องมือดีบักในตัวให้คุณ&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_gradle_เครื่องมือสำหรับ_build&quot;&gt;3. Gradle : เครื่องมือสำหรับ build&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;แม้ว่าแต่ละโปรเจกต์จะใช้ Gradle เวอร์ชันของตนเองผ่าน Gradle Wrapper การติดตั้ง Gradle แบบส่วนกลางก็มีประโยชน์สำหรับงานต่างๆ เช่น การเริ่มต้นโปรเจกต์ใหม่ (&lt;code&gt;gradle init&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การติดตั้งผ่าน_sdkman&quot;&gt;การติดตั้งผ่าน SDKMAN!&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เช่นเดียวกับกรณีของ JDK, SDKMAN! ทำให้การติดตั้ง Gradle ง่ายขึ้น&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ติดตั้ง_gradle&quot;&gt;ติดตั้ง Gradle&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sdk install gradle&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ตรวจสอบการติดตั้ง_2&quot;&gt;ตรวจสอบการติดตั้ง&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle -v&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;คำสั่งนี้จะแสดงเวอร์ชันของ Gradle, Kotlin, Groovy และ JDK ที่ใช้งาน&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_jbake_เครื่องมือสร้างเว็บไซต์แบบสแตติก&quot;&gt;4. JBake : เครื่องมือสร้างเว็บไซต์แบบสแตติก&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake คือเครื่องมือที่เราจะใช้ในการแปลงไฟล์ต้นฉบับของเรา (เช่นไฟล์นี้) ให้เป็นเว็บไซต์แบบสแตติก การติดตั้งไว้ในเครื่องนั้นสะดวกสำหรับการดูตัวอย่างการเปลี่ยนแปลง&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การติดตั้งผ่าน_sdkman_2&quot;&gt;การติดตั้งผ่าน SDKMAN!&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เช่นเดียวกับเครื่องมืออื่น ๆ SDKMAN! เป็นวิธีที่ง่ายที่สุด&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ติดตั้ง_jbake&quot;&gt;&lt;strong&gt;ติดตั้ง &lt;code&gt;JBake&lt;/code&gt;&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sdk install jbake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ตรวจสอบการติดตั้ง_3&quot;&gt;&lt;strong&gt;ตรวจสอบการติดตั้ง&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;jbake -v&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;คำสั่งนี้จะแสดงเวอร์ชันของ JBake และข้อมูลสภาพแวดล้อม Java ที่ใช้งาน&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_gradle_wrapper_แนวปฏิบัติที่ดีที่สุดอย่างแท้จริง&quot;&gt;5. Gradle Wrapper : แนวปฏิบัติที่ดีที่สุดอย่างแท้จริง&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เมื่อสร้างโปรเจกต์ของคุณเสร็จแล้ว (ซึ่งเราจะดูในบทความถัดไป) คุณไม่ควรใช้คำสั่งโกลบอลอีกต่อไป`gradle`. แทนที่จะเป็นเช่นนั้น คุณจะใช้&lt;strong&gt;Gradle Wrapper&lt;/strong&gt;(&lt;code&gt;./gradlew&lt;/code&gt;), สคริปต์ที่รวมอยู่ในโปรเจกต์ของคุณ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ทำไม?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ความสามารถในการทำซ้ำ:&lt;/strong&gt;Wrapper รับประกันว่าทุกคนที่ทำงานในโปรเจกต์ (รวมถึงเซิร์ฟเวอร์ CI/CD ของคุณ) ใช้&amp;#8230;&amp;#8203;อย่างแม่นยำ&lt;strong&gt;เวอร์ชัน Gradle เดียวกัน&lt;/strong&gt;, จึงขจัดข้อผิดพลาดในการ build ที่เกิดจากสภาพแวดล้อมที่แตกต่างกัน&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ความเรียบง่าย:&lt;/strong&gt;ไม่จำเป็นต้องติดตั้ง Gradle ด้วยตนเองเพื่อมีส่วนร่วมในโปรเจกต์&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพียงโคลนรีโพซิทอรีและรัน`./gradlew`ไม่มีข้อความภาษาฝรั่งเศสให้แปลค่ะ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;คำสั่งทั่วไปจะมีลักษณะดังนี้:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Ne pas faire : gradle build
# À faire :
./gradlew build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_6_docker_และ_portainer_สำหรับการบิลด์ที่ทำซ้ำได้_ไม่บังคับ&quot;&gt;6. Docker และ Portainer : สำหรับการบิลด์ที่ทำซ้ำได้ (ไม่บังคับ)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;แม้ว่าจะไม่จำเป็นอย่างเคร่งครัดสำหรับการเขียนปลั๊กอิน Docker และ Portainer ก็เป็นเครื่องมือ DevOps สมัยใหม่ที่ช่วยอำนวยความสะดวกอย่างมากในการสร้างบิลด์ที่ทำซ้ำได้และการจัดการสภาพแวดล้อมของคุณ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การติดตั้ง_docker_engine&quot;&gt;การติดตั้ง Docker Engine&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Docker ช่วยให้คุณแพ็กแอปพลิเคชันและส่วนที่ต้องพึ่งพาของคุณไว้ในคอนเทนเนอร์&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ติดตั้ง_docker_ผ่านสคริปต์อย่างเป็นทางการ&quot;&gt;&lt;strong&gt;ติดตั้ง Docker ผ่านสคริปต์อย่างเป็นทางการ:&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -fsSL https://get.docker.com -o get-docker.sh sudo sh get-docker.sh&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_จัดการ_docker_โดยไม่ใช้_sudo_แนะนำ&quot;&gt;&lt;strong&gt;จัดการ Docker โดยไม่ใช้ &lt;code&gt;sudo&lt;/code&gt; (แนะนำ):&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพิ่มผู้ใช้ของคุณลงในกลุ่ม`docker`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo usod -aG docker $USER&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;Important&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;

&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker run hello-world&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_จัดการ_docker_ด้วย_portainer_gui&quot;&gt;จัดการ Docker ด้วย Portainer (GUI)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Portainer เป็นอินเทอร์เฟซเว็บแบบเบาสำหรับจัดการคอนเทนเนอร์ Docker ของคุณ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_สร้างโวลุ่มสำหรับข้อมูลของ_portainer&quot;&gt;&lt;strong&gt;สร้างโวลุ่มสำหรับข้อมูลของ Portainer :&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker volume create portainer_data&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_เริ่มคอนเทนเนอร์_portainer&quot;&gt;&lt;strong&gt;เริ่มคอนเทนเนอร์ Portainer:&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker run -d -p 8000:8000 -p 9443:9443 --name portainer --restart=always -v /var/run/docker.sock:/var/run/docker.sock -v portainer_data:/data portainer/portainer-ce:latest&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตอนนี้คุณสามารถเข้าถึงอินเทอร์เฟซของ Portainer ได้ที่`https://localhost:9443`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทสรุป&quot;&gt;บทสรุป&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สภาพแวดล้อมของคุณพร้อมแล้ว! คุณมี JDK, IDE ที่เหมาะสมที่สุด, Gradle และ JBake ด้วยการเพิ่ม Docker คุณยังพร้อมสำหรับการสร้างบิลด์ที่บรรจุในคอนเทนเนอร์และทำซ้ำได้ รากฐานที่มั่นคงนี้จะช่วยให้คุณมุ่งเน้นไปที่สิ่งสำคัญ: การพัฒนาปลั๊กอินที่ทรงพลังและมีประโยชน์&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในบทความถัดไป เราจะใช้คำสั่ง`gradle init`เพื่อสร้างโครงสร้างของโปรเจกต์ปลั๊กอินแรกของเรา&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_การรวมเข้ากับ_poetry&quot;&gt;การรวมเข้ากับ Poetry&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_การติดตั้ง_poetry&quot;&gt;การติดตั้ง Poetry&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การเริ่มต้นโครงการ&quot;&gt;การเริ่มต้นโครงการ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_เพิ่มและติดตั้งการพึ่งพิง&quot;&gt;เพิ่มและติดตั้งการพึ่งพิง&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การเผยแพร่โดยใช้_poetry&quot;&gt;การเผยแพร่โดยใช้ Poetry&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การ_build_ที่ทำซ้ำได้ด้วย_docker&quot;&gt;การ build ที่ทำซ้ำได้ด้วย Docker&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ตัวอย่าง_dockerfile&quot;&gt;ตัวอย่าง Dockerfile&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การบูรณาการใน_github_actions&quot;&gt;การบูรณาการใน GitHub Actions&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การเผยแพร่แบบมีเงื่อนไข&quot;&gt;การเผยแพร่แบบมีเงื่อนไข&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การทำให้การพึ่งพาอาศัยอัตโนมัติด้วย_renovate_และ_dependabot&quot;&gt;การทำให้การพึ่งพาอาศัยอัตโนมัติด้วย Renovate และ Dependabot&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dependabot&quot;&gt;Dependabot&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ปรับปรุง&quot;&gt;ปรับปรุง&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ไดอะแกรม_plantuml&quot;&gt;ไดอะแกรม PlantUML&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_กรณีการใช้งาน_cicd_ขั้นสูง&quot;&gt;กรณีการใช้งาน – CI/CD ขั้นสูง&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ลำดับ_การเผยแพร่แบบมีเงื่อนไข&quot;&gt;ลำดับ - การเผยแพร่แบบมีเงื่อนไข&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สถานะ_ไปป์ไลน์_cicd&quot;&gt;สถานะ – ไปป์ไลน์ CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การปรับใช้_สถาปัตยกรรม_cicd&quot;&gt;การปรับใช้ – สถาปัตยกรรม CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สรุป&quot;&gt;สรุป&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในสองส่วนแรกของชุดนี้ เรามี : - สร้าง pipeline CI/CD ที่ใช้งานได้สำหรับแอปพลิเคชัน Python โดยใช้ GitHub Actions และ PyPI ได้ทำให้ไปป์ไลน์นี้เป็นระบบอุตสาหกรรมด้วยการทดสอบหลายเวอร์ชัน การเผยแพร่แบบค่อยเป็นค่อยไปผ่าน Test PyPI และเครื่องมือด้านคุณภาพและความปลอดภัย&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในส่วนที่สามนี้, เราจะไป&lt;strong&gt;เกินกว่าการตีพิมพ์เพียงอย่างเดียวบน PyPI&lt;/strong&gt;เพื่อสร้างห่วงโซ่ CI/CD ที่สมบูรณ์ มั่นคง และเป็นมืออาชีพด้วย : - &lt;strong&gt;บทกวี&lt;/strong&gt;เพื่อบรรจุภัณฑ์ที่ทันสมัยและการจัดการขึ้นต่อกันอย่างเหมาะสม - &lt;strong&gt;ด็อกเกอร์&lt;/strong&gt;เพื่อสร้างบิลด์ที่สามารถทำซ้ำได้และหลายแพลตฟอร์ม - &lt;strong&gt;การเผยแพร่แบบมีเงื่อนไข&lt;/strong&gt;เพื่อจัดการสถานการณ์เช่น release candidates. - &lt;strong&gt;เครื่องมืออัตโนมัติ&lt;/strong&gt;(Renovate, Dependabot) เพื่อรักษา pipeline ให้ทันสมัยอย่างง่ายดาย&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การรวมเข้ากับ_poetry&quot;&gt;การรวมเข้ากับ Poetry&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Poetry แทนที่เครื่องมือการแพ็คเกจเดิม (setup.py, requirements.txt) โดยการรวมศูนย์การจัดการความขึ้นต่อและกระบวนการสร้างไว้ใน`pyproject.toml`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การติดตั้ง_poetry&quot;&gt;การติดตั้ง Poetry&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;shell&quot;&gt;# Installer Poetry
curl -sSL https://install.python-poetry.org | python3 -
# Vérifier la version
poetry --version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การเริ่มต้นโครงการ&quot;&gt;การเริ่มต้นโครงการ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;shell&quot;&gt;# Initialiser un nouveau projet avec Poetry
poetry init
# Suivre l&#39;assistant pour renseigner : nom, version, description, licence, dépendances.&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สร้างไฟล์`pyproject.toml`(empty)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;toml&quot;&gt;[tool.poetry]
name = &quot;playlist-downloader&quot;
version = &quot;0.1.0&quot;
description = &quot;CLI tool for managing YouTube playlists&quot;
authors = [&quot;Christophe Hérolivier &amp;lt;cheroliv@example.com&amp;gt;&quot;]

[tool.poetry.dependencies]
python = &quot;&amp;gt;=3.8&quot;
typer = &quot;^0.9.0&quot;
yt-dlp = &quot;^2023.7.6&quot;
google-api-python-client = &quot;^2.0.0&quot;
google-auth-oauthlib = &quot;^1.0.0&quot;

[tool.poetry.group.dev.dependencies]
pytest = &quot;^7.0&quot;
mypy = &quot;^1.0&quot;
bandit = &quot;^1.7&quot;
safety = &quot;^2.3&quot;
black = &quot;^23.0&quot;
ruff = &quot;^0.1&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_เพิ่มและติดตั้งการพึ่งพิง&quot;&gt;เพิ่มและติดตั้งการพึ่งพิง&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;shell&quot;&gt;poetry add typer yt-dlp google-api-python-client google-auth-oauthlib
poetry add --group dev pytest mypy black bandit safety ruff&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การเผยแพร่โดยใช้_poetry&quot;&gt;การเผยแพร่โดยใช้ Poetry&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Poetry จัดการการเผยแพร่ได้โดยเนทีฟ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;shell&quot;&gt;# Publication sur Test PyPI
poetry publish --build --repository test-pypi

# Publication sur PyPI
poetry publish --build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;คำสั่งนี้ใช้อัตโนมัติข้อมูลที่มีอยู่ใน`pyproject.toml`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การ_build_ที่ทำซ้ำได้ด้วย_docker&quot;&gt;การ build ที่ทำซ้ำได้ด้วย Docker&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อให้แน่ใจว่าการดำเนินการเหมือนกันในสภาพแวดล้อมการพัฒนา CI/CD และการผลิต Docker รวมเข้ากับ Poetry ได้อย่างสมบูรณ์&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ตัวอย่าง_dockerfile&quot;&gt;ตัวอย่าง Dockerfile&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;dockerfile&quot;&gt;FROM python:3.11-slim

WORKDIR /app
COPY pyproject.toml poetry.lock ./
RUN pip install poetry
RUN poetry install --no-root --only main

COPY . .

CMD [&quot;poetry&quot;, &quot;run&quot;, &quot;python&quot;, &quot;cli.py&quot;]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;สิ่งนี้รับประกัน : - สภาพแวดล้อม Python ที่คงที่ - การพึ่งพาที่ถูกล็อกโดยใช้`poetry.lock`. - ภาพที่สามารถทำงานได้บนทุกระบบที่รองรับ Docker.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การบูรณาการใน_github_actions&quot;&gt;การบูรณาการใน GitHub Actions&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;name: Docker Build

on:
  push:
    branches: [main]

jobs:
  build-docker:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Build Docker image
        run: docker build -t ghcr.io/${{ github.repository }}:latest .
      - name: Push Docker image
        run: docker push ghcr.io/${{ github.repository }}:latest&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การเผยแพร่แบบมีเงื่อนไข&quot;&gt;การเผยแพร่แบบมีเงื่อนไข&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในระบบการทำงานแบบมืออาชีพ ต้องสามารถเผยแพร่ได้เฉพาะในบางกรณีเท่านั้น : - ผู้ปล่อยรุ่นทดสอบไปยัง Test PyPI - เวอร์ชันที่เสถียรมุ่งไปยัง PyPI. - สร้างการบิลด์ Docker ที่ทริกเกอร์เฉพาะสำหรับ`main`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;- name: Publish to Test PyPI
  if: contains(github.ref, &#39;-rc&#39;)
  run: poetry publish --build --repository test-pypi

- name: Publish to PyPI
  if: startsWith(github.ref, &#39;refs/tags/v&#39;)
  run: poetry publish --build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;วิธีนี้ช่วยหลีกเลี่ยงการโพสต์โดยไม่ได้ตั้งใจ。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การทำให้การพึ่งพาอาศัยอัตโนมัติด้วย_renovate_และ_dependabot&quot;&gt;การทำให้การพึ่งพาอาศัยอัตโนมัติด้วย Renovate และ Dependabot&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อป้องกันไม่ให้การพึ่งพาอาศัยของคุณล้าสมัย, รวมเครื่องมืออัปเดตอัตโนมัติ.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dependabot&quot;&gt;Dependabot&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;version: 2
updates:
  - package-ecosystem: &quot;pip&quot;
    directory: &quot;/&quot;
    schedule:
      interval: &quot;weekly&quot;
  - package-ecosystem: &quot;github-actions&quot;
    directory: &quot;/&quot;
    schedule:
      interval: &quot;weekly&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dependabot เปิด Pull Request แต่ละสัปดาห์เพื่ออัปเดตการพึ่งพาของ Python และ GitHub Actions&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ปรับปรุง&quot;&gt;ปรับปรุง&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;json&quot;&gt;{
  &quot;extends&quot;: [&quot;config:base&quot;],
  &quot;packageRules&quot;: [
    {
      &quot;matchManagers&quot;: [&quot;pip&quot;],
      &quot;groupName&quot;: &quot;python-dependencies&quot;,
      &quot;schedule&quot;: [&quot;before 6am on monday&quot;]
    }
  ]
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Renovate ช่วยให้สามารถควบคุมได้ละเอียดมากขึ้น: กลุ่มของการพึ่งพา, การวางแผน และกฎขั้นสูง.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ไดอะแกรม_plantuml&quot;&gt;ไดอะแกรม PlantUML&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_กรณีการใช้งาน_cicd_ขั้นสูง&quot;&gt;กรณีการใช้งาน – CI/CD ขั้นสูง&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/usecase-cicd.svg&quot; alt=&quot;usecase cicd&quot; width=&quot;820&quot; height=&quot;317&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ลำดับ_การเผยแพร่แบบมีเงื่อนไข&quot;&gt;ลำดับ - การเผยแพร่แบบมีเงื่อนไข&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/sequence-cicd.svg&quot; alt=&quot;sequence cicd&quot; width=&quot;303&quot; height=&quot;571&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_สถานะ_ไปป์ไลน์_cicd&quot;&gt;สถานะ – ไปป์ไลน์ CI/CD&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/states-cicd.svg&quot; alt=&quot;states cicd&quot; width=&quot;336&quot; height=&quot;608&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การปรับใช้_สถาปัตยกรรม_cicd&quot;&gt;การปรับใช้ – สถาปัตยกรรม CI/CD&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/deployment-cicd.svg&quot; alt=&quot;deployment cicd&quot; width=&quot;535&quot; height=&quot;288&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สรุป&quot;&gt;สรุป&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ในส่วนที่สามนี้ เราได้เห็นอย่างไร: - อัปเดตบรรจุภัณฑ์ Python ด้วย Poetry. รับประกันว่าเป็นบิลด์ที่สามารถสร้างซ้ำได้ผ่าน Docker. ตั้งค่าการเผยแพร่แบบมีเงื่อนไข ทำให้การอัปเดตความขึ้นต่อกันเป็นอัตโนมัติ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตอนนี้คุณมี pipeline CI/CD แล้ว&lt;strong&gt;สมบูรณ์, อุตสาหกรรมและปลอดภัย&lt;/strong&gt;, พร้อมที่จะพัฒนาไปกับโครงการของคุณ&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;สารบัญ&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_บทนำ&quot;&gt;บทนำ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สถาปัตยกรรมของไปป์ไลน์_cicd&quot;&gt;สถาปัตยกรรมของไปป์ไลน์ CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_โครงสร้างโครงการ&quot;&gt;โครงสร้างโครงการ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การกำหนดค่าแพ็กเกจด้วย_pyproject_toml&quot;&gt;การกำหนดค่าแพ็กเกจด้วย pyproject.toml&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_เวิร์กโฟลว์_cicd_การทดสอบและคุณภาพ&quot;&gt;เวิร์กโฟลว์ CI/CD - การทดสอบและคุณภาพ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_เวิร์กโฟลว์การรีลีสและการดีพลอย&quot;&gt;เวิร์กโฟลว์การรีลีสและการดีพลอย&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_แผนภาพสถาปัตยกรรม&quot;&gt;แผนภาพสถาปัตยกรรม&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_แผนภาพลำดับ_กระบวนการปล่อยเวอร์ชัน&quot;&gt;แผนภาพลำดับ - กระบวนการปล่อยเวอร์ชัน&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_แผนภาพสถานะ_วงจรชีวิตของแพ็กเกจ&quot;&gt;แผนภาพสถานะ - วงจรชีวิตของแพ็กเกจ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_แผนภาพการปรับใช้_โครงสร้างพื้นฐาน_cicd&quot;&gt;แผนภาพการปรับใช้ - โครงสร้างพื้นฐาน CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ออบเจ็กต์และโมเดลของไปป์ไลน์&quot;&gt;ออบเจ็กต์และโมเดลของไปป์ไลน์&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_แผนภาพคลาส_โมเดล_cicd&quot;&gt;แผนภาพคลาส - โมเดล CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การกำหนดค่าความลับ&quot;&gt;การกำหนดค่าความลับ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ซีเคร็ตของ_github_actions&quot;&gt;ซีเคร็ตของ GitHub Actions&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การสร้างโทเค็น_pypi&quot;&gt;การสร้างโทเค็น PyPI&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สคริปต์สำหรับการพัฒนาในเครื่อง&quot;&gt;สคริปต์สำหรับการพัฒนาในเครื่อง&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_makefile&quot;&gt;Makefile&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_สคริปต์เวอร์ชัน&quot;&gt;สคริปต์เวอร์ชัน&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_แนวปฏิบัติที่ดีและข้อแนะนำ&quot;&gt;แนวปฏิบัติที่ดีและข้อแนะนำ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_การกำหนดเวอร์ชันเชิงความหมาย&quot;&gt;การกำหนดเวอร์ชันเชิงความหมาย&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_กลยุทธ์การแตกสาขา&quot;&gt;กลยุทธ์การแตกสาขา&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การทดสอบและความครอบคลุม&quot;&gt;การทดสอบและความครอบคลุม&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ความปลอดภัย&quot;&gt;ความปลอดภัย&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การเฝ้าติดตามและความสามารถในการสังเกตการณ์&quot;&gt;การเฝ้าติดตามและความสามารถในการสังเกตการณ์&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_เมตริกไปป์ไลน์&quot;&gt;เมตริกไปป์ไลน์&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_การแจ้งเตือน&quot;&gt;การแจ้งเตือน&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_บทสรุป&quot;&gt;บทสรุป&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_แหล่งข้อมูลเพิ่มเติม&quot;&gt;แหล่งข้อมูลเพิ่มเติม&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทนำ&quot;&gt;บทนำ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;วัตถุประสงค์: แปลงไปป์ไลน์แบบง่ายให้เป็นไปป์ไลน์ระดับอุตสาหกรรมที่แข็งแกร่ง โดยสอดคล้องกับมาตรฐานสมัยใหม่ด้านการแพ็กเกจและวิศวกรรมซอฟต์แวร์&lt;/div&gt;
&lt;p&gt;ในส่วนแรกของซีรีส์นี้ เราได้สร้างไปป์ไลน์ CI/CD ที่เรียบง่ายแต่มีประสิทธิภาพเพื่อทำการทดสอบและการเผยแพร่แพ็กเกจ Python บน PyPI ให้เป็นอัตโนมัติ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ถึงเวลาแล้วที่จะทำให้ไปป์ไลน์นี้เป็นมืออาชีพ ในส่วนที่สองนี้ เราจะ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;ย้ายไปยังมาตรฐานสมัยใหม่ pyproject.toml,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;เพิ่มเครื่องมือด้านคุณภาพและความปลอดภัย (Black, Mypy, Bandit, Safety),&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;จัดให้มีการทดสอบหลายเวอร์ชัน,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ผสานการดีพลอยแบบค่อยเป็นค่อยไปผ่าน Test PyPI,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ทำให้การจัดการเวอร์ชันเป็นอัตโนมัติ และปรับปรุงการเฝ้าระวังไปป์ไลน์&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เตรียมพร้อมที่จะก้าวจากไปป์ไลน์ที่ใช้งานได้ไปสู่โครงสร้างพื้นฐาน CI/CD ระดับมืออาชีพ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การปรับใช้แอปพลิเคชัน Python บน PyPI จำเป็นต้องมีไปป์ไลน์ CI/CD ที่แข็งแกร่งซึ่งทำให้การทดสอบ การสร้าง และการเผยแพร่แพ็กเกจเป็นอัตโนมัติ บทความนี้ลงรายละเอียดการจัดทำไปป์ไลน์แบบครบวงจรโดยใช้ GitHub Actions สำหรับแอปพลิเคชัน CLI Python โดยยึดตามแนวปฏิบัติที่ดีของระบบนิเวศ Python สมัยใหม่&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สถาปัตยกรรมของไปป์ไลน์_cicd&quot;&gt;สถาปัตยกรรมของไปป์ไลน์ CI/CD&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ไปป์ไลน์ที่เราจะสร้างขึ้นใช้แนวทางแบบหลายขั้นตอน:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/diag-plantuml-md5-8407fc150463522174b473d6eebcd79a.png&quot; alt=&quot;Diagram&quot; width=&quot;1021&quot; height=&quot;604&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_โครงสร้างโครงการ&quot;&gt;โครงสร้างโครงการ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;แอปพลิเคชัน CLI Python ที่พร้อมสำหรับการจัดจำหน่ายต้องปฏิบัติตามโครงสร้างมาตรฐาน:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;text&quot;&gt;playlist-downloader/
├── .github/
│   └── workflows/
│       ├── ci.yml
│       ├── release.yml
│       └── security.yml
├── src/
│   └── playlist_downloader/
│       ├── __init__.py
│       ├── cli.py
│       ├── core/
│       └── adapters/
├── tests/
│   ├── unit/
│   ├── integration/
│   └── conftest.py
├── docs/
├── pyproject.toml
├── requirements.txt
├── requirements-dev.txt
├── MANIFEST.in
├── README.md
├── LICENSE
└── CHANGELOG.md&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การกำหนดค่าแพ็กเกจด้วย_pyproject_toml&quot;&gt;การกำหนดค่าแพ็กเกจด้วย pyproject.toml&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ไฟล์`pyproject.toml`เป็นมาตรฐานสมัยใหม่สำหรับการกำหนดค่าแพ็กเกจ Python:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;toml&quot;&gt;[build-system]
requires = [&quot;setuptools&amp;gt;=45&quot;, &quot;wheel&quot;, &quot;setuptools_scm&amp;gt;=6.2&quot;]
build-backend = &quot;setuptools.build_meta&quot;

[project]
name = &quot;playlist-downloader&quot;
authors = [
    {name = &quot;Christophe Hérolivier&quot;, email = &quot;cheroliv@example.com&quot;},
]
description = &quot;CLI tool for YouTube playlist management&quot;
readme = &quot;README.md&quot;
requires-python = &quot;&amp;gt;=3.8&quot;
keywords = [&quot;youtube&quot;, &quot;playlist&quot;, &quot;cli&quot;, &quot;downloader&quot;]
license = {text = &quot;MIT&quot;}
classifiers = [
    &quot;Development Status :: 4 - Beta&quot;,
    &quot;Environment :: Console&quot;,
    &quot;Intended Audience :: End Users/Desktop&quot;,
    &quot;License :: OSI Approved :: MIT License&quot;,
    &quot;Operating System :: OS Independent&quot;,
    &quot;Programming Language :: Python :: 3&quot;,
    &quot;Programming Language :: Python :: 3.8&quot;,
    &quot;Programming Language :: Python :: 3.9&quot;,
    &quot;Programming Language :: Python :: 3.10&quot;,
    &quot;Programming Language :: Python :: 3.11&quot;,
    &quot;Topic :: Multimedia :: Sound/Audio&quot;,
    &quot;Topic :: Utilities&quot;,
]
dependencies = [
    &quot;typer&amp;gt;=0.9.0&quot;,
    &quot;yt-dlp&amp;gt;=2023.7.6&quot;,
    &quot;google-api-python-client&amp;gt;=2.0.0&quot;,
    &quot;google-auth-oauthlib&amp;gt;=1.0.0&quot;,
    &quot;pyyaml&amp;gt;=6.0&quot;,
    &quot;rich&amp;gt;=13.0.0&quot;,
]
dynamic = [&quot;version&quot;]

[project.optional-dependencies]
dev = [
    &quot;pytest&amp;gt;=7.0.0&quot;,
    &quot;pytest-cov&amp;gt;=4.0.0&quot;,
    &quot;pytest-mock&amp;gt;=3.10.0&quot;,
    &quot;black&amp;gt;=23.0.0&quot;,
    &quot;flake8&amp;gt;=6.0.0&quot;,
    &quot;mypy&amp;gt;=1.0.0&quot;,
    &quot;pre-commit&amp;gt;=3.0.0&quot;,
    &quot;tox&amp;gt;=4.0.0&quot;,
]
test = [
    &quot;pytest&amp;gt;=7.0.0&quot;,
    &quot;pytest-cov&amp;gt;=4.0.0&quot;,
    &quot;pytest-mock&amp;gt;=3.10.0&quot;,
]

[project.urls]
Homepage = &quot;https://github.com/cheroliv/playlist-downloader&quot;
Documentation = &quot;https://github.com/cheroliv/playlist-downloader#readme&quot;
Repository = &quot;https://github.com/cheroliv/playlist-downloader.git&quot;
&quot;Bug Tracker&quot; = &quot;https://github.com/cheroliv/playlist-downloader/issues&quot;

[project.scripts]
playlist-downloader = &quot;playlist_downloader.cli:main&quot;

[tool.setuptools_scm]
write_to = &quot;src/playlist_downloader/_version.py&quot;

[tool.setuptools.packages.find]
where = [&quot;src&quot;]

[tool.pytest.ini_options]
testpaths = [&quot;tests&quot;]
python_files = [&quot;test_*.py&quot;]
python_classes = [&quot;Test*&quot;]
python_functions = [&quot;test_*&quot;]
addopts = [
    &quot;--cov=src/playlist_downloader&quot;,
    &quot;--cov-report=html&quot;,
    &quot;--cov-report=term-missing&quot;,
    &quot;--cov-fail-under=85&quot;,
]

[tool.black]
line-length = 88
target-version = [&#39;py38&#39;]
include = &#39;\.pyi?$&#39;
extend-exclude = &#39;&#39;&#39;
/(
  \.eggs
  | \.git
  | \.hg
  | \.mypy_cache
  | \.tox
  | \.venv
  | _build
  | buck-out
  | build
  | dist
)/
&#39;&#39;&#39;

[tool.mypy]
python_version = &quot;3.8&quot;
warn_return_any = true
warn_unused_configs = true
disallow_untyped_defs = true
disallow_incomplete_defs = true
check_untyped_defs = true
disallow_untyped_decorators = true
no_implicit_optional = true
warn_redundant_casts = true
warn_unused_ignores = true
warn_no_return = true
warn_unreachable = true
strict_equality = true

[[tool.mypy.overrides]]
module = [
    &quot;yt_dlp.*&quot;,
    &quot;googleapiclient.*&quot;,
    &quot;google_auth_oauthlib.*&quot;,
]
ignore_missing_imports = true&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_เวิร์กโฟลว์_cicd_การทดสอบและคุณภาพ&quot;&gt;เวิร์กโฟลว์ CI/CD - การทดสอบและคุณภาพ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เวิร์กโฟลว์หลัก (&lt;code&gt;ci.yml&lt;/code&gt;) รันการทดสอบบน Python หลายเวอร์ชัน:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;name: CI

on:
  push:
    branches: [ main, develop ]
  pull_request:
    branches: [ main ]

jobs:
  test:
    runs-on: ubuntu-latest
    strategy:
      matrix:
        python-version: [&quot;3.8&quot;, &quot;3.9&quot;, &quot;3.10&quot;, &quot;3.11&quot;]

    steps:
    - uses: actions/checkout@v4
      with:
        fetch-depth: 0

    - name: Set up Python ${{ matrix.python-version }}
      uses: actions/setup-python@v4
      with:
        python-version: ${{ matrix.python-version }}

    - name: Cache dependencies
      uses: actions/cache@v3
      with:
        path: |
          ~/.cache/pip
          ~/.cache/pre-commit
        key: ${{ runner.os }}-pip-${{ hashFiles(&#39;**/requirements*.txt&#39;) }}
        restore-keys: |
          ${{ runner.os }}-pip-

    - name: Install dependencies
      run: |
        python -m pip install --upgrade pip
        pip install -e &quot;.[dev]&quot;

    - name: Lint with flake8
      run: |
        flake8 src tests --count --select=E9,F63,F7,F82 --show-source --statistics
        flake8 src tests --count --exit-zero --max-complexity=10 --max-line-length=88 --statistics

    - name: Check code formatting with Black
      run: black --check src tests

    - name: Type checking with mypy
      run: mypy src

    - name: Run tests with pytest
      run: |
        pytest tests/ -v --cov=src/playlist_downloader \
          --cov-report=xml --cov-report=term-missing

    - name: Upload coverage to Codecov
      uses: codecov/codecov-action@v3
      if: matrix.python-version == &#39;3.11&#39;
      with:
        file: ./coverage.xml
        flags: unittests
        name: codecov-umbrella

  security:
    runs-on: ubuntu-latest
    steps:
    - uses: actions/checkout@v4

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: &quot;3.11&quot;

    - name: Install dependencies
      run: |
        python -m pip install --upgrade pip
        pip install bandit[toml] safety

    - name: Run security checks with bandit
      run: bandit -r src/ -f json -o bandit-report.json

    - name: Check dependencies with safety
      run: safety check --json --output safety-report.json

    - name: Upload security reports
      uses: actions/upload-artifact@v3
      if: always()
      with:
        name: security-reports
        path: |
          bandit-report.json
          safety-report.json

  build:
    needs: [test, security]
    runs-on: ubuntu-latest
    steps:
    - uses: actions/checkout@v4
      with:
        fetch-depth: 0

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: &quot;3.11&quot;

    - name: Install build dependencies
      run: |
        python -m pip install --upgrade pip
        pip install build twine

    - name: Build package
      run: python -m build

    - name: Check package with twine
      run: twine check dist/*

    - name: Upload build artifacts
      uses: actions/upload-artifact@v3
      with:
        name: dist
        path: dist/&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_เวิร์กโฟลว์การรีลีสและการดีพลอย&quot;&gt;เวิร์กโฟลว์การรีลีสและการดีพลอย&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เวิร์กโฟลว์การรีลีส (&lt;code&gt;release.yml&lt;/code&gt;) จัดการการเผยแพร่อัตโนมัติบน PyPI :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;name: Release

on:
  push:
    tags:
      - &#39;v*.*.*&#39;
  workflow_dispatch:
    inputs:
      environment:
        description: &#39;Deployment environment&#39;
        required: true
        default: &#39;test&#39;
        type: choice
        options:
        - test
        - production

env:
  PYTHON_VERSION: &quot;3.11&quot;

jobs:
  release:
    runs-on: ubuntu-latest
    environment:
      name: ${{ github.event.inputs.environment || (startsWith(github.ref, &#39;refs/tags/&#39;) &amp;amp;&amp;amp; &#39;production&#39; || &#39;test&#39;) }}

    steps:
    - uses: actions/checkout@v4
      with:
        fetch-depth: 0

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: ${{ env.PYTHON_VERSION }}

    - name: Install dependencies
      run: |
        python -m pip install --upgrade pip
        pip install build twine

    - name: Build package
      run: python -m build

    - name: Check package
      run: twine check dist/*

    - name: Publish to Test PyPI
      if: github.event.inputs.environment == &#39;test&#39; || (startsWith(github.ref, &#39;refs/tags/&#39;) &amp;amp;&amp;amp; contains(github.ref, &#39;rc&#39;))
      env:
        TWINE_USERNAME: __token__
        TWINE_PASSWORD: ${{ secrets.TEST_PYPI_API_TOKEN }}
      run: |
        twine upload --repository testpypi dist/*

    - name: Publish to PyPI
      if: github.event.inputs.environment == &#39;production&#39; || (startsWith(github.ref, &#39;refs/tags/&#39;) &amp;amp;&amp;amp; !contains(github.ref, &#39;rc&#39;))
      env:
        TWINE_USERNAME: __token__
        TWINE_PASSWORD: ${{ secrets.PYPI_API_TOKEN }}
      run: |
        twine upload dist/*

    - name: Create GitHub Release
      if: startsWith(github.ref, &#39;refs/tags/&#39;)
      uses: actions/create-release@v1
      env:
        GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
      with:
        tag_name: ${{ github.ref }}
        release_name: Release ${{ github.ref }}
        draft: false
        prerelease: ${{ contains(github.ref, &#39;rc&#39;) }}

  post-release:
    needs: release
    runs-on: ubuntu-latest
    if: startsWith(github.ref, &#39;refs/tags/&#39;)

    steps:
    - uses: actions/checkout@v4

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: ${{ env.PYTHON_VERSION }}

    - name: Test installation from PyPI
      run: |
        sleep 60  # Attendre la propagation sur PyPI
        pip install playlist-downloader
        playlist-downloader --version

    - name: Update documentation
      run: |
        # Script pour mettre à jour la documentation
        echo &quot;Documentation updated for version ${GITHUB_REF#refs/tags/}&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_แผนภาพสถาปัตยกรรม&quot;&gt;แผนภาพสถาปัตยกรรม&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_แผนภาพลำดับ_กระบวนการปล่อยเวอร์ชัน&quot;&gt;แผนภาพลำดับ - กระบวนการปล่อยเวอร์ชัน&lt;/h3&gt;
