&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การกำหนดค่าความลับ&quot;&gt;การกำหนดค่าความลับ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อให้ไปป์ไลน์ทำงานได้ คุณต้องกำหนดค่าซีเคร็ตต่อไปนี้ใน GitHub:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ซีเคร็ตของ_github_actions&quot;&gt;ซีเคร็ตของ GitHub Actions&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;bash&quot;&gt;# Dans Settings &amp;gt; Secrets and variables &amp;gt; Actions

# Token PyPI pour la production
PYPI_API_TOKEN=pypi-...

# Token Test PyPI pour les pré-releases
TEST_PYPI_API_TOKEN=pypi-...

# Token GitHub pour créer les releases
GITHUB_TOKEN=(automatiquement fourni)

# Token Codecov (optionnel)
CODECOV_TOKEN=...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การสร้างโทเค็น_pypi&quot;&gt;การสร้างโทเค็น PyPI&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;bash&quot;&gt;# 1. Créer un compte sur PyPI et Test PyPI
# 2. Aller dans Account Settings &amp;gt; API tokens
# 3. Créer un token avec scope &quot;Entire account&quot; ou spécifique au projet
# 4. Format du token : pypi-AgEIcHlwaS5vcmc...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_สคริปต์สำหรับการพัฒนาในเครื่อง&quot;&gt;สคริปต์สำหรับการพัฒนาในเครื่อง&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;เพื่อความสะดวกในการพัฒนา ให้สร้างสคริปต์ยูทิลิตี้:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_makefile&quot;&gt;Makefile&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;makefile&quot;&gt;.PHONY: install test lint format security build clean release-test release-prod

install:
	pip install -e &quot;.[dev]&quot;

test:
	pytest tests/ -v --cov=src/playlist_downloader

lint:
	flake8 src tests
	mypy src

format:
	black src tests

security:
	bandit -r src/
	safety check

build:
	python -m build
	twine check dist/*

clean:
	rm -rf build/ dist/ *.egg-info/
	find . -type d -name __pycache__ -delete
	find . -name &quot;*.pyc&quot; -delete

release-test: clean build
	twine upload --repository testpypi dist/*

release-prod: clean build
	twine upload dist/*

pre-commit: format lint test security
	@echo &quot;✅ Prêt pour commit&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_สคริปต์เวอร์ชัน&quot;&gt;สคริปต์เวอร์ชัน&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;python&quot;&gt;#!/usr/bin/env python3
&quot;&quot;&quot;Script pour gérer les versions du projet.&quot;&quot;&quot;

import sys
import subprocess
from pathlib import Path

def get_current_version():
    &quot;&quot;&quot;Récupère la version actuelle depuis git.&quot;&quot;&quot;
    try:
        result = subprocess.run(
            [&quot;git&quot;, &quot;describe&quot;, &quot;--tags&quot;, &quot;--abbrev=0&quot;],
            capture_output=True,
            text=True,
            check=True
        )
        return result.stdout.strip()
    except subprocess.CalledProcessError:
        return &quot;0.0.0&quot;

def create_version_tag(version, message=None):
    &quot;&quot;&quot;Crée un tag de version.&quot;&quot;&quot;
    if not version.startswith(&#39;v&#39;):
        version = f&#39;v{version}&#39;

    tag_message = message or f&quot;Release {version}&quot;

    subprocess.run([&quot;git&quot;, &quot;tag&quot;, &quot;-a&quot;, version, &quot;-m&quot;, tag_message], check=True)
    print(f&quot;✅ Tag {version} créé&quot;)

    # Push le tag
    subprocess.run([&quot;git&quot;, &quot;push&quot;, &quot;origin&quot;, version], check=True)
    print(f&quot;✅ Tag {version} poussé vers origin&quot;)

if __name__ == &quot;__main__&quot;:
    if len(sys.argv) &amp;lt; 2:
        current = get_current_version()
        print(f&quot;Version actuelle: {current}&quot;)
        print(&quot;Usage: python version.py &amp;lt;new_version&amp;gt; [message]&quot;)
        sys.exit(1)

    new_version = sys.argv[1]
    message = sys.argv[2] if len(sys.argv) &amp;gt; 2 else None

    create_version_tag(new_version, message)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_แนวปฏิบัติที่ดีและข้อแนะนำ&quot;&gt;แนวปฏิบัติที่ดีและข้อแนะนำ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การกำหนดเวอร์ชันเชิงความหมาย&quot;&gt;การกำหนดเวอร์ชันเชิงความหมาย&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ใช้การกำหนดเวอร์ชันเชิงความหมาย (SemVer) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MAJOR.MINOR.PATCH&lt;/code&gt; (ex: 1.2.3)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MAJOR&lt;/code&gt;: การเปลี่ยนแปลงที่เข้ากันไม่ได้&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MINOR&lt;/code&gt;: ฟีเจอร์ใหม่ที่เข้ากันได้&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;PATCH&lt;/code&gt;: การแก้ไขบั๊กที่เข้ากันได้&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_กลยุทธ์การแตกสาขา&quot;&gt;กลยุทธ์การแตกสาขา&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;text&quot;&gt;main          ──●──●──●──●──●────●── (releases stables)
               /       /          /
develop    ──●──●──●──●──●──●──●──●── (développement)
            /     /        /
feature/xxx  ●──●──●──●──●──/ (fonctionnalités)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การทดสอบและความครอบคลุม&quot;&gt;การทดสอบและความครอบคลุม&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;ความครอบคลุมของโค้ดขั้นต่ำ: 85%&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;การทดสอบหน่วยสำหรับตรรกะทางธุรกิจ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;การทดสอบแบบบูรณาการสำหรับอะแดปเตอร์&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;การทดสอบแบบต้นจนจบสำหรับ CLI&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ความปลอดภัย&quot;&gt;ความปลอดภัย&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;การสแกน dependencies โดยอัตโนมัติ (Safety)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;การวิเคราะห์โค้ดแบบสแตติก (Bandit)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ห้ามเก็บความลับไว้ในโค้ดเด็ดขาด&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;การใช้โทเค็น PyPI เฉพาะ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_การเฝ้าติดตามและความสามารถในการสังเกตการณ์&quot;&gt;การเฝ้าติดตามและความสามารถในการสังเกตการณ์&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_เมตริกไปป์ไลน์&quot;&gt;เมตริกไปป์ไลน์&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;# .github/workflows/metrics.yml
name: Pipeline Metrics

on:
  workflow_run:
    workflows: [&quot;CI&quot;, &quot;Release&quot;]
    types: [completed]

jobs:
  metrics:
    runs-on: ubuntu-latest
    steps:
    - name: Collect metrics
      run: |
        echo &quot;Pipeline: ${{ github.event.workflow_run.name }}&quot;
        echo &quot;Status: ${{ github.event.workflow_run.conclusion }}&quot;
        echo &quot;Duration: ${{ github.event.workflow_run.updated_at - github.event.workflow_run.created_at }}&quot;
        # Envoyer vers système de monitoring&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_การแจ้งเตือน&quot;&gt;การแจ้งเตือน&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;# Ajout dans les workflows pour notifications
- name: Notify on failure
  if: failure()
  uses: 8398a7/action-slack@v3
  with:
    status: failure
    text: &quot;❌ Pipeline failed for ${{ github.repository }}&quot;
  env:
    SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK }}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_บทสรุป&quot;&gt;บทสรุป&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ไปป์ไลน์ CI/CD ที่สมบูรณ์นี้สำหรับ Python มีให้:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ระบบอัตโนมัติเต็มรูปแบบ&lt;/strong&gt;: จากการตรวจสอบโค้ดไปจนถึงการเผยแพร่&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ความปลอดภัย&lt;/strong&gt;: การสแกนอัตโนมัติและการจัดการความลับอย่างปลอดภัย&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;คุณภาพ&lt;/strong&gt;: การทดสอบหลายเวอร์ชัน, การ linting และความครอบคลุมของโค้ด&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ความน่าเชื่อถือ&lt;/strong&gt;: การปรับใช้แบบค่อยเป็นค่อยไปผ่าน Test PyPI&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;การตรวจสอบย้อนกลับ&lt;/strong&gt;: อาร์ติแฟกต์ รายงาน และรีลีส GitHub&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;การนำแนวปฏิบัติเหล่านี้ไปใช้ช่วยรับประกันกระบวนการจัดส่งที่แข็งแกร่งและเป็นมืออาชีพสำหรับแอปพลิเคชัน Python CLI ของคุณ อีกทั้งยังช่วยอำนวยความสะดวกในการบำรุงรักษาและการพัฒนาต่อยอดโครงการของคุณในระยะยาว&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_แหล่งข้อมูลเพิ่มเติม&quot;&gt;แหล่งข้อมูลเพิ่มเติม&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://packaging.python.org/&quot;&gt;คู่มือผู้ใช้การแพ็กเกจ Python&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.github.com/en/actions&quot;&gt;เอกสาร GitHub Actions&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://pypi.org/help/&quot;&gt;เอกสารช่วยเหลือ PyPI&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://semver.org/&quot;&gt;ข้อกำหนดการกำหนดเวอร์ชันเชิงความหมาย&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://keepachangelog.com/&quot;&gt;เก็บบันทึกการเปลี่ยนแปลง&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
