    Intro typescript
    &amp;lt;script src=&quot;01_types.js&quot;&amp;gt;&amp;lt;/script&amp;gt;
    &amp;lt;script src=&quot;02_data_structure.js&quot;&amp;gt;&amp;lt;/script&amp;gt;
