&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;modules&quot;&gt;โมดูล&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;โมดูลช่วยให้สามารถจัดระเบียบโค้ดออกเป็นหลายไฟล์ได้&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตัวอย่างการให้คะแนน:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-typescript&quot; data-lang=&quot;typescript&quot;&gt;// Dans un fichier math.ts
export const add = (a: number, b: number): number =&amp;gt; a + b;

// Dans un autre fichier
import { add } from &#39;./math&#39;;
let result = add(2, 3);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_ts&quot;&gt;&lt;span class=&quot;underline&quot;&gt;แนะนำ typescript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;promesses&quot;&gt;คำสัญญา&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Promise ถูกนำมาใช้เพื่อดำเนินการแบบ asynchronous&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตัวอย่างการระบุขนาด:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-typescript&quot; data-lang=&quot;typescript&quot;&gt;const promise = new Promise&amp;lt;string&amp;gt;((resolve) =&amp;gt; {
    // Code asynchrone ici
    resolve(&quot;Succès&quot;);
});

promise.then((result) =&amp;gt; {
    console.log(result);
});&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_ts&quot;&gt;&lt;span class=&quot;underline&quot;&gt;แนะนำ typescript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;async-await&quot;&gt;async/await&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;async/await` ช่วยให้การจัดการ promise ง่ายขึ้น&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ตัวอย่างการระบุขนาด:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-typescript&quot; data-lang=&quot;typescript&quot;&gt;const fetchData = async (): Promise&amp;lt;void&amp;gt; =&amp;gt; {
    const result = await someAsyncFunction();
    console.log(result);
};&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_ts&quot;&gt;&lt;span class=&quot;underline&quot;&gt;แนะนำ typescript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
