&amp;lt;/head&amp;gt;

&amp;lt;body&amp;gt;
    &amp;lt;header&amp;gt;
        &amp;lt;h1&amp;gt;Les bases de CSS&amp;lt;/h1&amp;gt;
    &amp;lt;/header&amp;gt;

    &amp;lt;main&amp;gt;
        &amp;lt;div class=&quot;flexbox&quot;&amp;gt;
            &amp;lt;h2&amp;gt;Flexbox&amp;lt;/h2&amp;gt;
            &amp;lt;ul&amp;gt;
                &amp;lt;li&amp;gt;boite 1&amp;lt;/li&amp;gt;
